insert into public.blog_posts (
  slug, category, author_name, status, published_at, reading_time_min, tags, title_en, title_el, title_ro, title_ar, title_de, title_pl, title_ru, excerpt_en, excerpt_el, excerpt_ro, excerpt_ar, excerpt_de, excerpt_pl, excerpt_ru, summary_en, summary_el, summary_ro, summary_ar, summary_de, summary_pl, summary_ru, content_en, content_el, content_ro, content_ar, content_de, content_pl, content_ru, seo_title_en, seo_title_el, seo_title_ro, seo_title_ar, seo_title_de, seo_title_pl, seo_title_ru, seo_description_en, seo_description_el, seo_description_ro, seo_description_ar, seo_description_de, seo_description_pl, seo_description_ru, tags_en, tags_el, tags_ro, tags_ar, tags_de, tags_pl, tags_ru
) values
('setting-up-a-company-in-cyprus', 'business', 'The Cyprus Lifestyle Desk', 'published', now() - interval '5 hours', 6, array['Doing business','Company formation','Relocation','Cyprus']::text[], 'Setting up a company in Cyprus, step by step', 'Ίδρυση εταιρείας στην Κύπρο, βήμα προς βήμα', 'Înființarea unei companii în Cipru, pas cu pas', 'تأسيس شركة في قبرص خطوة بخطوة', 'Ein Unternehmen in Zypern gründen, Schritt für Schritt', 'Zakładanie spółki na Cyprze, krok po kroku', 'Регистрация компании на Кипре, шаг за шагом', 'From choosing a structure to your first VAT return, the real sequence of starting a Cyprus company, with the forms, authorities and figures that actually apply.', 'Από την επιλογή νομικής μορφής μέχρι την πρώτη σας δήλωση VAT, η πραγματική σειρά των βημάτων για να ξεκινήσετε μια κυπριακή εταιρεία, με τα έντυπα, τις αρχές και τα ποσά που ισχύουν στην πράξη.', 'De la alegerea unei structuri până la prima declarație VAT, succesiunea reală a pașilor pentru a lansa o companie cipriotă, cu formularele, autoritățile și cifrele care se aplică în practică.', 'من اختيار الهيكل القانوني إلى أول إقرار VAT، التسلسل الفعلي لبدء شركة قبرصية، مع النماذج والجهات والأرقام التي تنطبق فعلاً.', 'Von der Wahl der Rechtsform bis zur ersten VAT-Erklärung: der tatsächliche Ablauf einer Unternehmensgründung in Zypern, mit den Formularen, Behörden und Zahlen, die wirklich gelten.', 'Od wyboru formy prawnej po pierwszą deklarację VAT, rzeczywista kolejność zakładania cypryjskiej spółki, wraz z formularzami, urzędami i kwotami, które faktycznie obowiązują.', 'От выбора организационно-правовой формы до первой декларации по НДС: реальная последовательность создания кипрской компании, с формами, ведомствами и цифрами, которые действительно применяются.', 'A practical, current guide to incorporating and registering a business in the Republic of Cyprus: the Registrar, tax and VAT, social insurance, and the ongoing obligations every company carries.', 'Ένας πρακτικός και επίκαιρος οδηγός για τη σύσταση και την εγγραφή μιας επιχείρησης στην Κυπριακή Δημοκρατία: ο Έφορος Εταιρειών, η φορολογία και το VAT, οι κοινωνικές ασφαλίσεις και οι διαρκείς υποχρεώσεις που φέρει κάθε εταιρεία.', 'Un ghid practic și actual pentru constituirea și înregistrarea unei afaceri în Republica Cipru: Registratorul, impozitele și VAT, asigurările sociale și obligațiile permanente pe care le are fiecare companie.', 'دليل عملي ومُحدَّث لتأسيس وتسجيل نشاط تجاري في جمهورية قبرص: مسجّل الشركات، والضرائب وVAT، والتأمينات الاجتماعية، والالتزامات المستمرة التي تتحملها كل شركة.', 'Ein praxisnaher, aktueller Leitfaden zur Gründung und Registrierung eines Unternehmens in der Republik Zypern: das Handelsregister, Steuern und VAT, Sozialversicherung und die laufenden Pflichten, die jedes Unternehmen trägt.', 'Praktyczny i aktualny przewodnik po rejestracji i zakładaniu działalności gospodarczej w Republice Cypryjskiej: rejestr spółek, podatki i VAT, ubezpieczenie społeczne oraz bieżące obowiązki, które spoczywają na każdej spółce.', 'Практическое и актуальное руководство по учреждению и регистрации бизнеса в Республике Кипр: реестр компаний, налоги и НДС, социальное страхование, а также текущие обязанности, которые несет каждая компания.', '<p>Starting a company in Cyprus is refreshingly orderly once you know the sequence. The island runs a low corporate tax rate, an English-speaking professional class and a single online portal for most of the paperwork, but the steps still have to happen in the right order. Here is how it actually goes.</p><h2>Decide the shape first</h2><p>Before any form is filed, you settle the aim, the legal structure and a simple business model with a financial plan. Most trading businesses incorporate as a private limited company, which is the entity the rest of this guide assumes. You also choose premises and an entity name at this stage, because both feed into incorporation.</p><h2>Incorporate through the Registrar</h2><p>Companies are formed through the Department of Registrar of Companies and Intellectual Property. The memorandum and articles of association must be drafted by a lawyer practising in the Republic of Cyprus, and the company is registered using form HE1. You can check whether your chosen name is free at companies.gov.cy, look up trademarks at intellectualproperty.gov.cy, and reserve a .cy domain at registry.nic.cy.</p><h2>Register with the tax and insurance authorities</h2><p>Once the company exists, you register with the Tax Department, register for VAT, and register for VIES if you will trade goods or services with other EU countries. You then register as an employer, or as self-employed, with the Social Insurance Services. The standard VAT rate is 19%, with reduced rates of 9%, 5% and 0% on specific categories, and a self-employed person must register for VAT once turnover passes 15,600 euros in any twelve-month period. Self-employed contributors pay social insurance at 16.6% of estimated earnings, and start-ups keep their start-up benefits for the first five years.</p><h2>The ongoing rhythm</h2><p>A Cyprus company keeps its accounting records for seven years and appoints an approved auditor, a profession overseen by the Institute of Certified Public Accountants of Cyprus. Corporate income tax is 12.5% of net profit, there is an annual company levy of 350 euros due by 30 June, and audited financial statements are filed on form HE32. The company must have a Cyprus-resident director and hold an annual board meeting, and VAT is filed every three months. None of this is heavy once an accountant is in place, which is the single most useful early hire.</p><h2>Who to call</h2><p>Two professionals make the difference at the start: a corporate lawyer for the incorporation and a licensed accountant for tax, VAT and payroll. You will find both in our <a href="/directory/g/professional">professional services directory</a>, and you can describe your situation to <a href="/ask">the concierge</a> to be pointed to the right specialist in your district. Thresholds and procedures change, so treat the government portal as authoritative for exact figures. Source: Point of Single Contact, businessincyprus.gov.cy.</p>', '<p>Η ίδρυση εταιρείας στην Κύπρο είναι εντυπωσιακά τακτοποιημένη μόλις μάθετε τη σειρά των βημάτων. Το νησί διαθέτει χαμηλό συντελεστή εταιρικής φορολογίας, μια αγγλόφωνη τάξη επαγγελματιών και μία ενιαία διαδικτυακή πύλη για το μεγαλύτερο μέρος της γραφειοκρατίας, όμως τα βήματα πρέπει και πάλι να γίνουν με τη σωστή σειρά. Δείτε πώς λειτουργεί στην πράξη.</p><h2>Αποφασίστε πρώτα τη μορφή</h2><p>Πριν κατατεθεί οποιοδήποτε έντυπο, καθορίζετε τον στόχο, τη νομική μορφή και ένα απλό επιχειρηματικό μοντέλο με χρηματοοικονομικό σχέδιο. Οι περισσότερες εμπορικές επιχειρήσεις συστήνονται ως ιδιωτικές εταιρείες περιορισμένης ευθύνης, μορφή που προϋποθέτει και ο υπόλοιπος οδηγός. Σε αυτό το στάδιο επιλέγετε επίσης τις εγκαταστάσεις και την επωνυμία της εταιρείας, καθώς και τα δύο συνδέονται με τη σύσταση.</p><h2>Συστήστε την εταιρεία μέσω του Εφόρου Εταιρειών</h2><p>Οι εταιρείες συστήνονται μέσω του Τμήματος Εφόρου Εταιρειών και Διανοητικής Ιδιοκτησίας. Το ιδρυτικό έγγραφο και το καταστατικό πρέπει να συνταχθούν από δικηγόρο που ασκεί το επάγγελμα στην Κυπριακή Δημοκρατία, και η εταιρεία εγγράφεται με το έντυπο HE1. Μπορείτε να ελέγξετε αν η επωνυμία που επιλέξατε είναι διαθέσιμη στο companies.gov.cy, να αναζητήσετε εμπορικά σήματα στο intellectualproperty.gov.cy και να δεσμεύσετε έναν τομέα .cy στο registry.nic.cy.</p><h2>Εγγραφείτε στις φορολογικές και ασφαλιστικές αρχές</h2><p>Μόλις η εταιρεία αποκτήσει υπόσταση, εγγράφεστε στο Τμήμα Φορολογίας, εγγράφεστε στο VAT και εγγράφεστε στο VIES αν πρόκειται να εμπορεύεστε αγαθά ή υπηρεσίες με άλλες χώρες της ΕΕ. Στη συνέχεια εγγράφεστε ως εργοδότης, ή ως αυτοεργοδοτούμενος, στις Υπηρεσίες Κοινωνικών Ασφαλίσεων. Ο βασικός συντελεστής VAT είναι 19%, με μειωμένους συντελεστές 9%, 5% και 0% σε συγκεκριμένες κατηγορίες, ενώ ένας αυτοεργοδοτούμενος πρέπει να εγγραφεί στο VAT μόλις ο κύκλος εργασιών του ξεπεράσει τα 15.600 ευρώ σε οποιαδήποτε περίοδο δώδεκα μηνών. Οι αυτοεργοδοτούμενοι καταβάλλουν εισφορές κοινωνικών ασφαλίσεων ύψους 16,6% επί των εκτιμώμενων αποδοχών, και οι νεοφυείς επιχειρήσεις διατηρούν τα ευεργετήματα εκκίνησης για τα πρώτα πέντε χρόνια.</p><h2>Ο διαρκής ρυθμός</h2><p>Μια κυπριακή εταιρεία τηρεί τα λογιστικά της αρχεία για επτά χρόνια και διορίζει εγκεκριμένο ελεγκτή, επάγγελμα που εποπτεύεται από τον Σύνδεσμο Εγκεκριμένων Λογιστών Κύπρου. Ο εταιρικός φόρος εισοδήματος ανέρχεται σε 12,5% επί των καθαρών κερδών, υπάρχει ετήσιο εταιρικό τέλος 350 ευρώ που καταβάλλεται μέχρι τις 30 Ιουνίου, και οι ελεγμένες οικονομικές καταστάσεις υποβάλλονται με το έντυπο HE32. Η εταιρεία πρέπει να έχει διοικητικό σύμβουλο που είναι κάτοικος Κύπρου και να πραγματοποιεί ετήσια συνεδρίαση του διοικητικού συμβουλίου, ενώ το VAT υποβάλλεται κάθε τρεις μήνες. Τίποτε από αυτά δεν είναι βαρύ μόλις αναλάβει ένας λογιστής, που είναι η πιο χρήσιμη πρώιμη πρόσληψη.</p><h2>Σε ποιον να απευθυνθείτε</h2><p>Δύο επαγγελματίες κάνουν τη διαφορά στην αρχή: ένας εταιρικός δικηγόρος για τη σύσταση και ένας αδειούχος λογιστής για τη φορολογία, το VAT και τη μισθοδοσία. Θα βρείτε και τους δύο στον <a href="/directory/g/professional">κατάλογο επαγγελματικών υπηρεσιών</a> μας, και μπορείτε να περιγράψετε την περίπτωσή σας στον <a href="/ask">σύμβουλο εξυπηρέτησης</a> για να κατευθυνθείτε στον κατάλληλο ειδικό στην περιοχή σας. Τα όρια και οι διαδικασίες αλλάζουν, γι'' αυτό θεωρήστε την κυβερνητική πύλη ως την αυθεντική πηγή για τα ακριβή ποσά. Πηγή: Ενιαίο Κέντρο Εξυπηρέτησης, businessincyprus.gov.cy.</p>', '<p>Înființarea unei companii în Cipru este surprinzător de ordonată odată ce cunoști succesiunea pașilor. Insula are o cotă redusă de impozitare a companiilor, o clasă de profesioniști vorbitori de engleză și un singur portal online pentru cea mai mare parte a formalităților, însă pașii trebuie totuși parcurși în ordinea corectă. Iată cum se desfășoară în realitate.</p><h2>Stabilește mai întâi forma</h2><p>Înainte de a depune orice formular, stabilești obiectivul, forma juridică și un model de afaceri simplu, însoțit de un plan financiar. Cele mai multe afaceri comerciale se constituie ca societate cu răspundere limitată de tip privat, forma pe care o presupune și restul acestui ghid. În această etapă alegi de asemenea sediul și denumirea entității, deoarece ambele influențează constituirea.</p><h2>Constituie compania prin Registrator</h2><p>Companiile se constituie prin Departamentul Registratorului Societăților și Proprietății Intelectuale. Actul constitutiv și statutul trebuie redactate de un avocat care profesează în Republica Cipru, iar compania se înregistrează folosind formularul HE1. Poți verifica dacă denumirea aleasă este liberă la companies.gov.cy, poți căuta mărci comerciale la intellectualproperty.gov.cy și poți rezerva un domeniu .cy la registry.nic.cy.</p><h2>Înregistrează-te la autoritățile fiscale și de asigurări</h2><p>Odată ce compania există, te înregistrezi la Departamentul Fiscal, te înregistrezi pentru VAT și te înregistrezi pentru VIES dacă vei tranzacționa bunuri sau servicii cu alte țări din UE. Apoi te înregistrezi ca angajator, sau ca lucrător independent, la Serviciile de Asigurări Sociale. Cota standard de VAT este de 19%, cu cote reduse de 9%, 5% și 0% pentru anumite categorii, iar un lucrător independent trebuie să se înregistreze pentru VAT de îndată ce cifra de afaceri depășește 15.600 de euro în orice perioadă de douăsprezece luni. Contribuabilii independenți plătesc asigurări sociale în cotă de 16,6% din veniturile estimate, iar întreprinderile nou-înființate își păstrează beneficiile de start pentru primii cinci ani.</p><h2>Ritmul continuu</h2><p>O companie cipriotă își păstrează evidențele contabile timp de șapte ani și numește un auditor autorizat, o profesie supravegheată de Institutul Contabililor Publici Autorizați din Cipru. Impozitul pe profitul companiilor este de 12,5% din profitul net, există o taxă anuală de companie de 350 de euro, scadentă până la 30 iunie, iar situațiile financiare auditate se depun pe formularul HE32. Compania trebuie să aibă un administrator rezident în Cipru și să țină o adunare anuală a consiliului, iar declarația de VAT se depune la fiecare trei luni. Nimic din toate acestea nu este împovărător odată ce ai un contabil, care este cea mai utilă angajare timpurie.</p><h2>Pe cine să contactezi</h2><p>Doi profesioniști fac diferența la început: un avocat specializat în dreptul societăților pentru constituire și un contabil autorizat pentru impozite, VAT și salarizare. Îi vei găsi pe amândoi în <a href="/directory/g/professional">directorul nostru de servicii profesionale</a>, iar situația ta o poți descrie <a href="/ask">concierge-ului</a> pentru a fi îndrumat către specialistul potrivit din zona ta. Pragurile și procedurile se schimbă, așa că tratează portalul guvernamental drept sursă autoritară pentru cifrele exacte. Sursă: Punctul de Contact Unic, businessincyprus.gov.cy.</p>', '<p>تأسيس شركة في قبرص عملية منظمة على نحو مريح بمجرد أن تعرف التسلسل. تتمتع الجزيرة بمعدل ضريبة شركات منخفض، وطبقة مهنية تتحدث الإنجليزية، وبوابة إلكترونية واحدة لمعظم المعاملات الورقية، لكن الخطوات يجب مع ذلك أن تجري بالترتيب الصحيح. وإليك كيف تسير الأمور فعلاً.</p><h2>حدّد الهيكل أولاً</h2><p>قبل تقديم أي نموذج، تحدّد الهدف والهيكل القانوني ونموذج عمل بسيط مع خطة مالية. تتأسس معظم الأنشطة التجارية كشركة خاصة محدودة المسؤولية، وهي الكيان الذي يفترضه بقية هذا الدليل. كما تختار في هذه المرحلة مقر العمل واسم الكيان، لأن كليهما يدخل في عملية التأسيس.</p><h2>التأسيس عبر مسجّل الشركات</h2><p>تُؤسَّس الشركات عبر دائرة مسجّل الشركات والملكية الفكرية. ويجب أن يصوغ عقد التأسيس والنظام الأساسي محامٍ يمارس المهنة في جمهورية قبرص، وتُسجَّل الشركة باستخدام النموذج HE1. ويمكنك التحقق مما إذا كان الاسم الذي اخترته متاحاً على companies.gov.cy، والبحث عن العلامات التجارية على intellectualproperty.gov.cy، وحجز نطاق .cy على registry.nic.cy.</p><h2>التسجيل لدى سلطات الضرائب والتأمينات</h2><p>بمجرد وجود الشركة، تسجّلها لدى دائرة الضرائب، وتسجّلها لأغراض VAT، وتسجّلها في نظام VIES إذا كنت ستتاجر في السلع أو الخدمات مع دول أخرى في الاتحاد الأوروبي. ثم تسجّل نفسك بصفتك صاحب عمل أو عاملاً لحسابك الخاص لدى دوائر التأمينات الاجتماعية. ويبلغ معدل VAT القياسي 19%، مع معدلات مخفّضة قدرها 9% و5% و0% على فئات محددة، ويجب على العامل لحسابه الخاص أن يسجّل لأغراض VAT بمجرد أن يتجاوز رقم أعماله 15,600 يورو خلال أي فترة اثني عشر شهراً. ويدفع المشتركون العاملون لحسابهم الخاص اشتراكات التأمينات الاجتماعية بنسبة 16.6% من الدخل المقدَّر، وتحتفظ المشاريع الناشئة بمزايا الانطلاق طوال السنوات الخمس الأولى.</p><h2>الإيقاع المستمر</h2><p>تحتفظ الشركة القبرصية بسجلاتها المحاسبية لمدة سبع سنوات وتعيّن مدقّق حسابات معتمداً، وهي مهنة يشرف عليها معهد المحاسبين القانونيين المعتمدين في قبرص. وتبلغ ضريبة دخل الشركات 12.5% من صافي الربح، وهناك رسم سنوي على الشركة قدره 350 يورو يُستحق بحلول 30 يونيو، وتُقدَّم البيانات المالية المدقَّقة على النموذج HE32. ويجب أن يكون للشركة مدير مقيم في قبرص وأن تعقد اجتماعاً سنوياً لمجلس الإدارة، ويُقدَّم إقرار VAT كل ثلاثة أشهر. ولا شيء من هذا مرهق بمجرد وجود محاسب، وهو أكثر تعيين مبكر فائدة على الإطلاق.</p><h2>بمن تتصل</h2><p>يُحدث اختصاصيان الفارق في البداية: محامي شركات لعملية التأسيس ومحاسب مرخّص للضرائب وVAT وكشوف الرواتب. وستجد كليهما في <a href="/directory/g/professional">دليل الخدمات المهنية</a> لدينا، ويمكنك عرض وضعك على <a href="/ask">الكونسيرج</a> ليوجّهك إلى الأخصائي المناسب في منطقتك. تتغير الحدود والإجراءات، لذا اعتبر البوابة الحكومية المرجع الموثوق للأرقام الدقيقة. المصدر: نقطة الاتصال الموحّدة، businessincyprus.gov.cy.</p>', '<p>Ein Unternehmen in Zypern zu gründen, ist erfrischend geordnet, sobald man die Reihenfolge kennt. Die Insel bietet einen niedrigen Körperschaftsteuersatz, eine englischsprachige Fachwelt und ein einziges Online-Portal für den Großteil der Formalitäten, doch die Schritte müssen dennoch in der richtigen Reihenfolge erfolgen. So läuft es tatsächlich ab.</p><h2>Zuerst die Struktur festlegen</h2><p>Bevor ein Formular eingereicht wird, legen Sie das Ziel, die Rechtsform und ein einfaches Geschäftsmodell samt Finanzplan fest. Die meisten Handelsunternehmen werden als private Gesellschaft mit beschränkter Haftung gegründet, und von dieser Rechtsform geht der Rest dieses Leitfadens aus. In dieser Phase wählen Sie außerdem die Geschäftsräume und einen Firmennamen, denn beides fließt in die Gründung ein.</p><h2>Gründung über das Handelsregister</h2><p>Unternehmen werden über die Abteilung des Registers der Gesellschaften und des geistigen Eigentums gegründet. Der Gesellschaftsvertrag und die Satzung müssen von einer in der Republik Zypern zugelassenen Anwältin oder einem zugelassenen Anwalt erstellt werden, und das Unternehmen wird mit dem Formular HE1 eingetragen. Ob Ihr gewünschter Name frei ist, prüfen Sie auf companies.gov.cy, Marken recherchieren Sie auf intellectualproperty.gov.cy, und eine .cy-Domain reservieren Sie auf registry.nic.cy.</p><h2>Registrierung bei den Steuer- und Versicherungsbehörden</h2><p>Sobald das Unternehmen besteht, registrieren Sie es bei der Steuerbehörde, melden es für VAT an und registrieren es für VIES, wenn Sie Waren oder Dienstleistungen mit anderen EU-Ländern handeln. Anschließend melden Sie sich als Arbeitgeber oder als Selbstständiger bei den Sozialversicherungsdiensten an. Der VAT-Regelsatz beträgt 19 %, mit ermäßigten Sätzen von 9 %, 5 % und 0 % für bestimmte Kategorien, und Selbstständige müssen sich für VAT registrieren, sobald der Umsatz in einem beliebigen Zwölfmonatszeitraum 15.600 Euro übersteigt. Selbstständige Beitragszahler leisten Sozialversicherungsbeiträge in Höhe von 16,6 % der geschätzten Einkünfte, und Existenzgründer behalten ihre Gründungsvergünstigungen für die ersten fünf Jahre.</p><h2>Der laufende Rhythmus</h2><p>Ein zyprisches Unternehmen bewahrt seine Buchführungsunterlagen sieben Jahre lang auf und bestellt einen zugelassenen Wirtschaftsprüfer, einen Berufsstand, der vom Institut der zugelassenen Wirtschaftsprüfer Zyperns beaufsichtigt wird. Die Körperschaftsteuer beträgt 12,5 % des Nettogewinns, es gibt eine jährliche Unternehmensabgabe von 350 Euro, fällig bis zum 30. Juni, und geprüfte Jahresabschlüsse werden mit dem Formular HE32 eingereicht. Das Unternehmen muss einen in Zypern ansässigen Direktor haben und eine jährliche Vorstandssitzung abhalten, und VAT wird alle drei Monate erklärt. Nichts davon ist aufwendig, sobald ein Buchhalter an Bord ist, was die mit Abstand nützlichste frühe Einstellung ist.</p><h2>An wen Sie sich wenden</h2><p>Zwei Fachleute machen den Unterschied am Anfang: eine Wirtschaftsanwältin für die Gründung und ein zugelassener Buchhalter für Steuern, VAT und Lohnabrechnung. Beide finden Sie in unserem <a href="/directory/g/professional">Verzeichnis professioneller Dienstleistungen</a>, und Sie können Ihre Situation <a href="/ask">dem Concierge</a> schildern, um an den richtigen Fachmann in Ihrem Bezirk verwiesen zu werden. Schwellenwerte und Verfahren ändern sich, betrachten Sie daher das Regierungsportal als maßgeblich für genaue Zahlen. Quelle: Einheitlicher Ansprechpartner, businessincyprus.gov.cy.</p>', '<p>Zakładanie spółki na Cyprze jest zaskakująco uporządkowane, gdy tylko pozna się właściwą kolejność działań. Wyspa oferuje niską stawkę podatku dochodowego od osób prawnych, anglojęzyczne środowisko specjalistów oraz jeden portal internetowy do załatwienia większości formalności, jednak poszczególne kroki i tak trzeba wykonać we właściwej kolejności. Oto jak wygląda to w praktyce.</p><h2>Najpierw zdecyduj o formie</h2><p>Zanim złożysz jakikolwiek formularz, ustalasz cel, formę prawną oraz prosty model biznesowy wraz z planem finansowym. Większość firm handlowych rejestruje się jako prywatna spółka z ograniczoną odpowiedzialnością i to właśnie taką formę zakłada dalsza część niniejszego przewodnika. Na tym etapie wybierasz również lokal oraz nazwę podmiotu, ponieważ obie te kwestie mają wpływ na proces rejestracji.</p><h2>Zarejestruj spółkę w rejestrze spółek</h2><p>Spółki zakłada się za pośrednictwem Departamentu Rejestru Spółek i Własności Intelektualnej. Umowa spółki oraz statut muszą zostać sporządzone przez prawnika praktykującego w Republice Cypryjskiej, a spółkę rejestruje się na formularzu HE1. Dostępność wybranej nazwy można sprawdzić na stronie companies.gov.cy, znaki towarowe wyszukać na intellectualproperty.gov.cy, a domenę .cy zarezerwować na registry.nic.cy.</p><h2>Zarejestruj się w urzędach podatkowych i ubezpieczeniowych</h2><p>Gdy spółka już istnieje, rejestrujesz ją w urzędzie podatkowym, rejestrujesz się do VAT oraz do systemu VIES, jeśli zamierzasz handlować towarami lub usługami z innymi krajami UE. Następnie rejestrujesz się w służbie ubezpieczeń społecznych jako pracodawca lub jako osoba prowadząca działalność na własny rachunek. Standardowa stawka VAT wynosi 19%, przy stawkach obniżonych 9%, 5% i 0% dla określonych kategorii, a osoba samozatrudniona musi zarejestrować się do VAT, gdy jej obrót przekroczy 15 600 euro w dowolnym okresie dwunastu miesięcy. Osoby prowadzące działalność na własny rachunek opłacają ubezpieczenie społeczne w wysokości 16,6% szacowanych dochodów, a nowe firmy zachowują ulgi dla firm rozpoczynających działalność przez pierwsze pięć lat.</p><h2>Bieżący rytm obowiązków</h2><p>Cypryjska spółka przechowuje dokumentację księgową przez siedem lat i powołuje uprawnionego biegłego rewidenta, którego zawód nadzoruje Instytut Dyplomowanych Księgowych Cypru. Podatek dochodowy od osób prawnych wynosi 12,5% zysku netto, obowiązuje roczna opłata od spółki w wysokości 350 euro płatna do 30 czerwca, a zbadane sprawozdania finansowe składa się na formularzu HE32. Spółka musi mieć dyrektora będącego rezydentem Cypru i co roku odbywać posiedzenie zarządu, a deklaracje VAT składa się co trzy miesiące. Żaden z tych obowiązków nie jest uciążliwy, gdy tylko zatrudni się księgowego, co jest najbardziej przydatnym wczesnym zatrudnieniem.</p><h2>Do kogo się zwrócić</h2><p>Na starcie różnicę robi dwoje specjalistów: prawnik korporacyjny przy rejestracji spółki oraz licencjonowany księgowy zajmujący się podatkami, VAT i płacami. Obu znajdziesz w naszym <a href="/directory/g/professional">katalogu usług profesjonalnych</a>, a swoją sytuację możesz opisać <a href="/ask">konsjerżowi</a>, aby skierował cię do właściwego specjalisty w twoim rejonie. Progi i procedury się zmieniają, dlatego w kwestii dokładnych kwot za wiążący traktuj portal rządowy. Źródło: Pojedynczy Punkt Kontaktowy, businessincyprus.gov.cy.</p>', '<p>Открыть компанию на Кипре на удивление просто и упорядоченно, как только вы усвоите правильную последовательность действий. На острове действует низкая ставка налога на прибыль, работает англоязычное профессиональное сообщество и существует единый онлайн-портал для большинства формальностей, однако все шаги по-прежнему нужно выполнять в правильном порядке. Вот как это происходит на самом деле.</p><h2>Сначала определитесь с формой</h2><p>Прежде чем подать хоть одну форму, вы определяете цель, организационно-правовую форму и простую бизнес-модель с финансовым планом. Большинство торговых предприятий регистрируются как частная компания с ограниченной ответственностью, и именно такую форму подразумевает остальная часть этого руководства. На этом этапе вы также выбираете помещение и наименование компании, поскольку и то и другое влияет на процесс регистрации.</p><h2>Регистрация через реестр компаний</h2><p>Компании создаются через Департамент реестра компаний и интеллектуальной собственности. Учредительный договор и устав должны быть составлены юристом, практикующим в Республике Кипр, а компания регистрируется по форме HE1. Проверить, свободно ли выбранное вами наименование, можно на сайте companies.gov.cy, товарные знаки посмотреть на intellectualproperty.gov.cy, а домен .cy зарезервировать на registry.nic.cy.</p><h2>Регистрация в налоговых органах и органах страхования</h2><p>Как только компания создана, вы регистрируете ее в налоговом департаменте, регистрируетесь по НДС и по системе VIES, если будете торговать товарами или услугами с другими странами ЕС. Затем вы регистрируетесь в службе социального страхования как работодатель или как самозанятый. Стандартная ставка НДС составляет 19%, при пониженных ставках 9%, 5% и 0% для отдельных категорий, а самозанятое лицо обязано зарегистрироваться по НДС, как только оборот превысит 15 600 евро за любой двенадцатимесячный период. Самозанятые плательщики отчисляют взносы на социальное страхование в размере 16,6% от предполагаемого дохода, а начинающие предприятия сохраняют льготы для стартапов в течение первых пяти лет.</p><h2>Текущий ритм обязанностей</h2><p>Кипрская компания хранит бухгалтерскую документацию в течение семи лет и назначает утвержденного аудитора, профессию которого курирует Институт дипломированных бухгалтеров Кипра. Налог на прибыль составляет 12,5% чистой прибыли, действует ежегодный сбор с компании в размере 350 евро со сроком уплаты до 30 июня, а прошедшая аудит финансовая отчетность подается по форме HE32. Компания должна иметь директора, являющегося резидентом Кипра, и ежегодно проводить заседание совета директоров, а декларации по НДС подаются каждые три месяца. Ни одна из этих обязанностей не является обременительной, как только появляется бухгалтер, и это самый полезный сотрудник на раннем этапе.</p><h2>К кому обратиться</h2><p>На старте разницу создают два специалиста: корпоративный юрист для регистрации компании и лицензированный бухгалтер для налогов, НДС и расчета заработной платы. Обоих вы найдете в нашем <a href="/directory/g/professional">каталоге профессиональных услуг</a>, а описать свою ситуацию можно <a href="/ask">консьержу</a>, чтобы он направил вас к нужному специалисту в вашем районе. Пороговые значения и процедуры меняются, поэтому в отношении точных цифр считайте авторитетным государственный портал. Источник: Единая контактная точка, businessincyprus.gov.cy.</p>', 'How to set up a company in Cyprus: a step-by-step guide', 'Πώς να ιδρύσετε εταιρεία στην Κύπρο: ένας οδηγός βήμα προς βήμα', 'Cum să înființezi o companie în Cipru: un ghid pas cu pas', 'كيفية تأسيس شركة في قبرص: دليل خطوة بخطوة', 'Ein Unternehmen in Zypern gründen: eine Schritt-für-Schritt-Anleitung', 'Jak założyć spółkę na Cyprze: przewodnik krok po kroku', 'Как открыть компанию на Кипре: пошаговое руководство', 'Incorporating in Cyprus, step by step: the Registrar of Companies, tax and VAT registration, social insurance, the 12.5% corporate rate and the annual obligations.', 'Σύσταση εταιρείας στην Κύπρο, βήμα προς βήμα: ο Έφορος Εταιρειών, η εγγραφή στη φορολογία και στο VAT, οι κοινωνικές ασφαλίσεις, ο εταιρικός συντελεστής 12,5% και οι ετήσιες υποχρεώσεις.', 'Constituirea unei companii în Cipru, pas cu pas: Registratorul Societăților, înregistrarea pentru impozite și VAT, asigurările sociale, cota de impozitare corporativă de 12,5% și obligațiile anuale.', 'التأسيس في قبرص خطوة بخطوة: مسجّل الشركات، وتسجيل الضرائب وVAT، والتأمينات الاجتماعية، ومعدل ضريبة الشركات البالغ 12.5%، والالتزامات السنوية.', 'Gründung in Zypern, Schritt für Schritt: das Handelsregister, Steuer- und VAT-Registrierung, Sozialversicherung, der Körperschaftsteuersatz von 12,5 % und die jährlichen Pflichten.', 'Zakładanie spółki na Cyprze krok po kroku: rejestr spółek, rejestracja do podatków i VAT, ubezpieczenie społeczne, stawka CIT 12,5% oraz obowiązki roczne.', 'Учреждение компании на Кипре шаг за шагом: реестр компаний, регистрация по налогам и НДС, социальное страхование, ставка налога на прибыль 12,5% и ежегодные обязанности.', array['Doing business','Company formation','Relocation','Cyprus']::text[], array['Επιχειρείν','Ίδρυση εταιρείας','Μετεγκατάσταση','Κύπρος']::text[], array['Afaceri','Înființarea companiei','Relocare','Cipru']::text[], array['ممارسة الأعمال','تأسيس الشركات','الانتقال','قبرص']::text[], array['Geschäftstätigkeit','Unternehmensgründung','Umzug','Zypern']::text[], array['Prowadzenie działalności','Zakładanie spółki','Relokacja','Cypr']::text[], array['Ведение бизнеса','Регистрация компании','Переезд','Кипр']::text[]),
('cyprus-tax-and-vat-guide', 'business', 'The Cyprus Lifestyle Desk', 'published', now() - interval '11 hours', 6, array['Tax','VAT','Doing business','Cyprus']::text[], 'Tax and VAT in Cyprus: what residents and businesses owe', 'Φορολογία και VAT στην Κύπρο: τι οφείλουν οι κάτοικοι και οι επιχειρήσεις', 'Impozite și VAT în Cipru: ce datorează rezidenții și companiile', 'الضرائب وVAT في قبرص: ما الذي يدين به المقيمون والشركات', 'Steuern und VAT in Zypern: was Einwohner und Unternehmen schulden', 'Podatki i VAT na Cyprze: co płacą mieszkańcy i przedsiębiorcy', 'Налоги и НДС на Кипре: что платят резиденты и бизнес', 'The income tax bands, the VAT thresholds and the filing deadlines that decide your year, set out plainly and with the current figures.', 'Οι φορολογικές κλίμακες εισοδήματος, τα όρια για το VAT και οι προθεσμίες υποβολής που καθορίζουν τη χρονιά σας, διατυπωμένα με σαφήνεια και με τα τρέχοντα ποσά.', 'Tranșele de impozit pe venit, pragurile de VAT și termenele de depunere care îți hotărăsc anul, prezentate clar și cu cifrele actuale.', 'شرائح ضريبة الدخل، وحدود VAT، والمواعيد النهائية لتقديم الإقرارات التي تحدد عامك، معروضة بوضوح ومع الأرقام الحالية.', 'Die Einkommensteuerstufen, die VAT-Schwellenwerte und die Abgabefristen, die Ihr Jahr bestimmen, klar dargelegt und mit den aktuellen Zahlen.', 'Przedziały podatku dochodowego, progi VAT oraz terminy składania deklaracji, które wyznaczają twój rok, przedstawione przystępnie i z aktualnymi liczbami.', 'Шкала подоходного налога, пороги по НДС и сроки подачи деклараций, которые определяют ваш год, изложенные просто и с актуальными цифрами.', 'A clear guide to personal income tax bands, VAT registration and the tax calendar in the Republic of Cyprus, with the thresholds, portal and forms that apply now.', 'Ένας σαφής οδηγός για τις κλίμακες του φόρου εισοδήματος φυσικών προσώπων, την εγγραφή στο VAT και το φορολογικό ημερολόγιο στην Κυπριακή Δημοκρατία, με τα όρια, την πύλη και τα έντυπα που ισχύουν σήμερα.', 'Un ghid clar despre tranșele de impozit pe venitul persoanelor fizice, înregistrarea pentru VAT și calendarul fiscal din Republica Cipru, cu pragurile, portalul și formularele care se aplică în prezent.', 'دليل واضح لشرائح ضريبة الدخل الشخصي، والتسجيل في VAT، والروزنامة الضريبية في جمهورية قبرص، مع الحدود والبوابة والنماذج المطبَّقة الآن.', 'Ein klarer Leitfaden zu den Stufen der persönlichen Einkommensteuer, zur VAT-Registrierung und zum Steuerkalender in der Republik Zypern, mit den Schwellenwerten, dem Portal und den Formularen, die jetzt gelten.', 'Przejrzysty przewodnik po przedziałach podatku dochodowego od osób fizycznych, rejestracji do VAT i kalendarzu podatkowym w Republice Cypryjskiej, wraz z progami, portalem i formularzami, które obowiązują obecnie.', 'Понятное руководство по шкале подоходного налога с физических лиц, регистрации по НДС и налоговому календарю в Республике Кипр, с порогами, порталом и формами, которые действуют сейчас.', '<p>Cyprus is not a no-tax island, but it is a clear one. Income tax is banded, VAT is conventional, and almost everything is filed through one portal. Here is what a resident or a business actually owes, and when.</p><h2>Income tax</h2><p>Income tax is administered by the Cyprus Tax Department, and you register and file through the TAX FOR ALL portal at taxforall.mof.gov.cy. For 2025, individuals with gross income above 19,500 euros must register. For the 2026 tax year the bands are 0% on income up to 22,000 euros, 20% from 22,001 to 32,000, 25% from 32,001 to 42,000, 30% from 42,001 to 72,000, and 35% above 72,001. From 2026 the registration net also widens to include tax residents aged 25 to 70 regardless of income.</p><h2>VAT</h2><p>You must register for VAT with the Tax Department once taxable transactions exceed, or are about to exceed, 15,600 euros over the preceding twelve months or the coming thirty days. A separate threshold of 10,251.61 euros applies to acquisitions from other EU member states. Registration uses form T.D. 1101 with proof of taxable activity, and is completed online through the TAX FOR ALL portal. The standard rate is 19%, with reduced rates of 9%, 5% and 0%, VAT returns are filed every quarter, and declarations are due by the tenth day of the second month after each period. If you trade within the EU, you also register for VIES.</p><h2>The calendar that matters</h2><p>Income tax returns are due fifteen months after the end of the tax year. Self-assessments fall due on 1 August for companies and high-turnover self-employed, and 30 June for others. Employee declarations are due by 31 July and employer declarations by 30 April. Corporate income tax is 12.5% of net profit, and companies also carry the annual levy of 350 euros due by 30 June.</p><h2>Get it set once, then it runs</h2><p>Most of this is a first-year setup problem, not an every-week burden. A licensed accountant will register you correctly and keep the calendar for you, and you will find accountants and tax advisers in our <a href="/directory/g/professional">professional services directory</a>. To be matched to one in your district, describe your situation to <a href="/ask">the concierge</a>. Rates and applicable years change, so treat the government portal as authoritative. Source: Point of Single Contact, businessincyprus.gov.cy.</p>', '<p>Η Κύπρος δεν είναι νησί χωρίς φόρους, είναι όμως ένα νησί με σαφήνεια. Ο φόρος εισοδήματος είναι κλιμακωτός, το VAT είναι συμβατικό και σχεδόν τα πάντα υποβάλλονται μέσω μίας πύλης. Δείτε τι πραγματικά οφείλει ένας κάτοικος ή μια επιχείρηση, και πότε.</p><h2>Φόρος εισοδήματος</h2><p>Ο φόρος εισοδήματος διαχειρίζεται από το Κυπριακό Τμήμα Φορολογίας, και η εγγραφή και η υποβολή γίνονται μέσω της πύλης TAX FOR ALL στο taxforall.mof.gov.cy. Για το 2025, τα φυσικά πρόσωπα με ακαθάριστο εισόδημα άνω των 19.500 ευρώ πρέπει να εγγραφούν. Για το φορολογικό έτος 2026, οι κλίμακες είναι 0% για εισόδημα έως 22.000 ευρώ, 20% από 22.001 έως 32.000, 25% από 32.001 έως 42.000, 30% από 42.001 έως 72.000 και 35% άνω των 72.001. Από το 2026, το πεδίο εγγραφής διευρύνεται επίσης ώστε να περιλαμβάνει τους φορολογικούς κατοίκους ηλικίας 25 έως 70 ετών, ανεξαρτήτως εισοδήματος.</p><h2>VAT</h2><p>Πρέπει να εγγραφείτε στο VAT στο Τμήμα Φορολογίας μόλις οι φορολογητέες συναλλαγές υπερβούν, ή πρόκειται να υπερβούν, τα 15.600 ευρώ κατά τους προηγούμενους δώδεκα μήνες ή τις επόμενες τριάντα ημέρες. Ένα χωριστό όριο 10.251,61 ευρώ ισχύει για αποκτήσεις από άλλα κράτη μέλη της ΕΕ. Η εγγραφή γίνεται με το έντυπο T.D. 1101 με αποδεικτικά στοιχεία φορολογητέας δραστηριότητας και ολοκληρώνεται διαδικτυακά μέσω της πύλης TAX FOR ALL. Ο βασικός συντελεστής είναι 19%, με μειωμένους συντελεστές 9%, 5% και 0%, οι δηλώσεις VAT υποβάλλονται κάθε τρίμηνο και οι δηλώσεις οφείλονται μέχρι τη δέκατη ημέρα του δεύτερου μήνα μετά από κάθε περίοδο. Αν εμπορεύεστε εντός της ΕΕ, εγγράφεστε επίσης στο VIES.</p><h2>Το ημερολόγιο που μετράει</h2><p>Οι δηλώσεις φόρου εισοδήματος οφείλονται δεκαπέντε μήνες μετά το τέλος του φορολογικού έτους. Οι αυτοφορολογίες οφείλονται την 1η Αυγούστου για τις εταιρείες και τους αυτοεργοδοτούμενους με υψηλό κύκλο εργασιών, και στις 30 Ιουνίου για τους υπόλοιπους. Οι δηλώσεις των εργαζομένων οφείλονται μέχρι τις 31 Ιουλίου και οι δηλώσεις των εργοδοτών μέχρι τις 30 Απριλίου. Ο εταιρικός φόρος εισοδήματος ανέρχεται σε 12,5% επί των καθαρών κερδών, και οι εταιρείες φέρουν επίσης το ετήσιο τέλος των 350 ευρώ που καταβάλλεται μέχρι τις 30 Ιουνίου.</p><h2>Ρυθμίστε το μία φορά και μετά τρέχει μόνο του</h2><p>Το μεγαλύτερο μέρος αυτών είναι ζήτημα ρύθμισης του πρώτου έτους, όχι εβδομαδιαίο βάρος. Ένας αδειούχος λογιστής θα σας εγγράψει σωστά και θα τηρεί το ημερολόγιο για εσάς, και θα βρείτε λογιστές και φορολογικούς συμβούλους στον <a href="/directory/g/professional">κατάλογο επαγγελματικών υπηρεσιών</a> μας. Για να αντιστοιχιστείτε με κάποιον στην περιοχή σας, περιγράψτε την περίπτωσή σας στον <a href="/ask">σύμβουλο εξυπηρέτησης</a>. Οι συντελεστές και τα έτη εφαρμογής αλλάζουν, γι'' αυτό θεωρήστε την κυβερνητική πύλη ως αυθεντική πηγή. Πηγή: Ενιαίο Κέντρο Εξυπηρέτησης, businessincyprus.gov.cy.</p>', '<p>Cipru nu este o insulă fără impozite, dar este una clară. Impozitul pe venit este pe tranșe, VAT este unul obișnuit, iar aproape totul se depune printr-un singur portal. Iată ce datorează în realitate un rezident sau o companie, și când.</p><h2>Impozitul pe venit</h2><p>Impozitul pe venit este administrat de Departamentul Fiscal din Cipru, iar înregistrarea și depunerea se fac prin portalul TAX FOR ALL la taxforall.mof.gov.cy. Pentru 2025, persoanele fizice cu un venit brut de peste 19.500 de euro trebuie să se înregistreze. Pentru anul fiscal 2026, tranșele sunt 0% pentru venitul de până la 22.000 de euro, 20% de la 22.001 la 32.000, 25% de la 32.001 la 42.000, 30% de la 42.001 la 72.000 și 35% peste 72.001. Din 2026, sfera de înregistrare se lărgește de asemenea pentru a include rezidenții fiscali cu vârste între 25 și 70 de ani, indiferent de venit.</p><h2>VAT</h2><p>Trebuie să te înregistrezi pentru VAT la Departamentul Fiscal de îndată ce tranzacțiile impozabile depășesc, sau sunt pe cale să depășească, 15.600 de euro în ultimele douăsprezece luni sau în următoarele treizeci de zile. Un prag separat de 10.251,61 euro se aplică achizițiilor din alte state membre ale UE. Înregistrarea se face cu formularul T.D. 1101, însoțit de dovada activității impozabile, și se finalizează online prin portalul TAX FOR ALL. Cota standard este de 19%, cu cote reduse de 9%, 5% și 0%, declarațiile de VAT se depun trimestrial, iar declarațiile sunt scadente până în a zecea zi a celei de-a doua luni de după fiecare perioadă. Dacă tranzacționezi în interiorul UE, te înregistrezi de asemenea pentru VIES.</p><h2>Calendarul care contează</h2><p>Declarațiile de impozit pe venit sunt scadente la cincisprezece luni după încheierea anului fiscal. Autoevaluările sunt scadente la 1 august pentru companii și pentru lucrătorii independenți cu cifră de afaceri mare, și la 30 iunie pentru ceilalți. Declarațiile angajaților sunt scadente până la 31 iulie, iar declarațiile angajatorilor până la 30 aprilie. Impozitul pe profitul companiilor este de 12,5% din profitul net, iar companiile suportă de asemenea taxa anuală de 350 de euro, scadentă până la 30 iunie.</p><h2>Configureaz-o o dată, apoi merge singură</h2><p>Cea mai mare parte a acestor lucruri este o problemă de configurare în primul an, nu o povară săptămânală. Un contabil autorizat te va înregistra corect și va ține calendarul în locul tău, iar contabili și consultanți fiscali vei găsi în <a href="/directory/g/professional">directorul nostru de servicii profesionale</a>. Pentru a fi pus în legătură cu unul din zona ta, descrie-ți situația <a href="/ask">concierge-ului</a>. Cotele și anii de aplicare se schimbă, așa că tratează portalul guvernamental drept sursă autoritară. Sursă: Punctul de Contact Unic, businessincyprus.gov.cy.</p>', '<p>قبرص ليست جزيرة معفاة من الضرائب، لكنها جزيرة واضحة. فضريبة الدخل مقسَّمة إلى شرائح، وVAT تقليدية، ويُقدَّم كل شيء تقريباً عبر بوابة واحدة. وإليك ما يدين به المقيم أو الشركة فعلاً، ومتى.</p><h2>ضريبة الدخل</h2><p>تتولى دائرة الضرائب القبرصية إدارة ضريبة الدخل، وتسجّل وتقدّم إقراراتك عبر بوابة TAX FOR ALL على taxforall.mof.gov.cy. وبالنسبة لعام 2025، يجب على الأفراد الذين يتجاوز دخلهم الإجمالي 19,500 يورو التسجيل. وفي السنة الضريبية 2026 تكون الشرائح 0% على الدخل حتى 22,000 يورو، و20% من 22,001 إلى 32,000، و25% من 32,001 إلى 42,000، و30% من 42,001 إلى 72,000، و35% فوق 72,001. واعتباراً من 2026 يتّسع نطاق التسجيل أيضاً ليشمل المقيمين الضريبيين الذين تتراوح أعمارهم بين 25 و70 عاماً بصرف النظر عن الدخل.</p><h2>VAT</h2><p>يجب أن تسجّل لأغراض VAT لدى دائرة الضرائب بمجرد أن تتجاوز المعاملات الخاضعة للضريبة، أو تكون على وشك أن تتجاوز، 15,600 يورو خلال الاثني عشر شهراً السابقة أو الثلاثين يوماً المقبلة. وينطبق حد منفصل قدره 10,251.61 يورو على المشتريات من دول أعضاء أخرى في الاتحاد الأوروبي. ويتم التسجيل باستخدام النموذج T.D. 1101 مع إثبات النشاط الخاضع للضريبة، ويُستكمل إلكترونياً عبر بوابة TAX FOR ALL. ويبلغ المعدل القياسي 19%، مع معدلات مخفّضة قدرها 9% و5% و0%، وتُقدَّم إقرارات VAT كل ربع سنة، وتُستحق الإقرارات بحلول اليوم العاشر من الشهر الثاني بعد كل فترة. وإذا كنت تتاجر داخل الاتحاد الأوروبي، فإنك تسجّل أيضاً في نظام VIES.</p><h2>الروزنامة التي تهم</h2><p>تُستحق إقرارات ضريبة الدخل بعد خمسة عشر شهراً من نهاية السنة الضريبية. وتُستحق التقديرات الذاتية في 1 أغسطس بالنسبة للشركات والعاملين لحسابهم الخاص من ذوي رقم الأعمال المرتفع، وفي 30 يونيو للآخرين. وتُستحق إقرارات الموظفين بحلول 31 يوليو وإقرارات أصحاب العمل بحلول 30 أبريل. وتبلغ ضريبة دخل الشركات 12.5% من صافي الربح، وتتحمل الشركات أيضاً الرسم السنوي البالغ 350 يورو المستحق بحلول 30 يونيو.</p><h2>اضبطها مرة واحدة، ثم تسير من تلقاء نفسها</h2><p>معظم هذا مسألة إعداد في السنة الأولى، لا عبء أسبوعي. فالمحاسب المرخّص سيسجّلك بشكل صحيح ويتابع الروزنامة نيابةً عنك، وستجد المحاسبين والمستشارين الضريبيين في <a href="/directory/g/professional">دليل الخدمات المهنية</a> لدينا. وللمطابقة مع أحدهم في منطقتك، اعرض وضعك على <a href="/ask">الكونسيرج</a>. تتغير المعدلات والسنوات المطبَّقة، لذا اعتبر البوابة الحكومية المرجع الموثوق. المصدر: نقطة الاتصال الموحّدة، businessincyprus.gov.cy.</p>', '<p>Zypern ist keine steuerfreie Insel, aber eine übersichtliche. Die Einkommensteuer ist gestaffelt, VAT ist konventionell, und fast alles wird über ein einziges Portal eingereicht. Hier steht, was ein Einwohner oder ein Unternehmen tatsächlich schuldet, und wann.</p><h2>Einkommensteuer</h2><p>Die Einkommensteuer wird von der zyprischen Steuerbehörde verwaltet, und Sie registrieren sich und reichen Ihre Erklärungen über das Portal TAX FOR ALL unter taxforall.mof.gov.cy ein. Für 2025 müssen sich Personen mit einem Bruttoeinkommen über 19.500 Euro registrieren. Für das Steuerjahr 2026 gelten die Stufen 0 % bei Einkommen bis 22.000 Euro, 20 % von 22.001 bis 32.000, 25 % von 32.001 bis 42.000, 30 % von 42.001 bis 72.000 und 35 % über 72.001. Ab 2026 erweitert sich der Kreis der Registrierungspflichtigen zudem auf steuerlich Ansässige im Alter von 25 bis 70 Jahren, unabhängig vom Einkommen.</p><h2>VAT</h2><p>Sie müssen sich bei der Steuerbehörde für VAT registrieren, sobald die steuerpflichtigen Umsätze in den vorangegangenen zwölf Monaten oder den kommenden dreißig Tagen 15.600 Euro übersteigen oder zu übersteigen drohen. Für Erwerbe aus anderen EU-Mitgliedstaaten gilt ein gesonderter Schwellenwert von 10.251,61 Euro. Die Registrierung erfolgt mit dem Formular T.D. 1101 samt Nachweis der steuerpflichtigen Tätigkeit und wird online über das Portal TAX FOR ALL abgeschlossen. Der Regelsatz beträgt 19 %, mit ermäßigten Sätzen von 9 %, 5 % und 0 %; VAT-Erklärungen werden vierteljährlich eingereicht, und die Meldungen sind bis zum zehnten Tag des zweiten Monats nach jedem Zeitraum fällig. Wenn Sie innerhalb der EU handeln, registrieren Sie sich zusätzlich für VIES.</p><h2>Der Kalender, der zählt</h2><p>Einkommensteuererklärungen sind fünfzehn Monate nach Ende des Steuerjahres fällig. Selbstveranlagungen sind für Unternehmen und Selbstständige mit hohem Umsatz am 1. August fällig, für die übrigen am 30. Juni. Arbeitnehmererklärungen sind bis zum 31. Juli fällig, Arbeitgebererklärungen bis zum 30. April. Die Körperschaftsteuer beträgt 12,5 % des Nettogewinns, und Unternehmen tragen zudem die jährliche Abgabe von 350 Euro, fällig bis zum 30. Juni.</p><h2>Einmal richtig einrichten, dann läuft es</h2><p>Das meiste davon ist eine Einrichtungsfrage im ersten Jahr, keine wöchentliche Last. Ein zugelassener Buchhalter registriert Sie korrekt und führt den Kalender für Sie, und Buchhalter sowie Steuerberater finden Sie in unserem <a href="/directory/g/professional">Verzeichnis professioneller Dienstleistungen</a>. Um mit einem in Ihrem Bezirk zusammengebracht zu werden, schildern Sie Ihre Situation <a href="/ask">dem Concierge</a>. Sätze und geltende Jahre ändern sich, betrachten Sie daher das Regierungsportal als maßgeblich. Quelle: Einheitlicher Ansprechpartner, businessincyprus.gov.cy.</p>', '<p>Cypr nie jest wyspą bez podatków, ale jest wyspą przejrzystą. Podatek dochodowy jest progresywny, VAT typowy, a niemal wszystko rozlicza się przez jeden portal. Oto co faktycznie płaci mieszkaniec lub firma i w jakim terminie.</p><h2>Podatek dochodowy</h2><p>Podatkiem dochodowym zarządza cypryjski urząd podatkowy, a rejestracji i rozliczeń dokonuje się przez portal TAX FOR ALL pod adresem taxforall.mof.gov.cy. W 2025 roku obowiązek rejestracji mają osoby fizyczne o dochodzie brutto powyżej 19 500 euro. Dla roku podatkowego 2026 przedziały wynoszą 0% od dochodu do 22 000 euro, 20% od 22 001 do 32 000, 25% od 32 001 do 42 000, 30% od 42 001 do 72 000 oraz 35% powyżej 72 001. Od 2026 roku obowiązek rejestracji obejmie również rezydentów podatkowych w wieku od 25 do 70 lat, niezależnie od dochodu.</p><h2>VAT</h2><p>Do VAT musisz zarejestrować się w urzędzie podatkowym, gdy transakcje podlegające opodatkowaniu przekroczą lub mają przekroczyć 15 600 euro w ciągu poprzednich dwunastu miesięcy lub najbliższych trzydziestu dni. Odrębny próg 10 251,61 euro dotyczy nabyć z innych państw członkowskich UE. Rejestracji dokonuje się na formularzu T.D. 1101 wraz z dowodem prowadzenia działalności podlegającej opodatkowaniu, a całość załatwia się online przez portal TAX FOR ALL. Stawka standardowa wynosi 19%, przy stawkach obniżonych 9%, 5% i 0%, deklaracje VAT składa się co kwartał, a termin ich złożenia upływa dziesiątego dnia drugiego miesiąca po każdym okresie. Jeśli handlujesz w obrębie UE, rejestrujesz się również do systemu VIES.</p><h2>Kalendarz, który ma znaczenie</h2><p>Zeznania podatku dochodowego składa się w ciągu piętnastu miesięcy od zakończenia roku podatkowego. Termin samodzielnego rozliczenia przypada na 1 sierpnia w przypadku spółek i osób samozatrudnionych o wysokim obrocie oraz na 30 czerwca w przypadku pozostałych. Deklaracje pracowników należy złożyć do 31 lipca, a deklaracje pracodawców do 30 kwietnia. Podatek dochodowy od osób prawnych wynosi 12,5% zysku netto, a spółki ponoszą także roczną opłatę w wysokości 350 euro płatną do 30 czerwca.</p><h2>Ustaw to raz, a potem działa samo</h2><p>Większość z tego to kwestia jednorazowego ustawienia w pierwszym roku, a nie cotygodniowego obciążenia. Licencjonowany księgowy zarejestruje cię prawidłowo i będzie pilnował za ciebie kalendarza, a księgowych i doradców podatkowych znajdziesz w naszym <a href="/directory/g/professional">katalogu usług profesjonalnych</a>. Aby dobrać takiego specjalistę w twoim rejonie, opisz swoją sytuację <a href="/ask">konsjerżowi</a>. Stawki i lata, których dotyczą, się zmieniają, dlatego za wiążący traktuj portal rządowy. Źródło: Pojedynczy Punkt Kontaktowy, businessincyprus.gov.cy.</p>', '<p>Кипр не является островом без налогов, но он остров с прозрачной системой. Подоходный налог взимается по шкале, НДС устроен обычным образом, и почти все подается через один портал. Вот что на самом деле платит резидент или бизнес и в какие сроки.</p><h2>Подоходный налог</h2><p>Подоходным налогом управляет Налоговый департамент Кипра, а регистрация и подача деклараций осуществляются через портал TAX FOR ALL по адресу taxforall.mof.gov.cy. В 2025 году зарегистрироваться обязаны физические лица с валовым доходом свыше 19 500 евро. На 2026 налоговый год шкала составляет 0% с дохода до 22 000 евро, 20% с 22 001 до 32 000, 25% с 32 001 до 42 000, 30% с 42 001 до 72 000 и 35% свыше 72 001. С 2026 года обязанность по регистрации также распространяется на налоговых резидентов в возрасте от 25 до 70 лет независимо от дохода.</p><h2>НДС</h2><p>Зарегистрироваться по НДС в налоговом департаменте необходимо, как только облагаемые операции превысят или вот-вот превысят 15 600 евро за предыдущие двенадцать месяцев или предстоящие тридцать дней. Отдельный порог в 10 251,61 евро применяется к приобретениям из других государств-членов ЕС. Регистрация оформляется по форме T.D. 1101 с подтверждением облагаемой деятельности и завершается онлайн через портал TAX FOR ALL. Стандартная ставка составляет 19%, при пониженных ставках 9%, 5% и 0%, декларации по НДС подаются ежеквартально, а срок их подачи истекает на десятый день второго месяца после каждого периода. Если вы торгуете внутри ЕС, вы также регистрируетесь в системе VIES.</p><h2>Календарь, который важен</h2><p>Декларации по подоходному налогу подаются в течение пятнадцати месяцев после окончания налогового года. Срок самостоятельного расчета налога наступает 1 августа для компаний и самозанятых с высоким оборотом и 30 июня для остальных. Декларации работников должны быть поданы до 31 июля, а декларации работодателей до 30 апреля. Налог на прибыль составляет 12,5% чистой прибыли, а компании также несут ежегодный сбор в размере 350 евро со сроком уплаты до 30 июня.</p><h2>Настройте один раз, дальше работает само</h2><p>Большая часть этого относится к разовой настройке в первый год, а не к еженедельной нагрузке. Лицензированный бухгалтер зарегистрирует вас правильно и будет вести за вас календарь, а бухгалтеров и налоговых консультантов вы найдете в нашем <a href="/directory/g/professional">каталоге профессиональных услуг</a>. Чтобы подобрать такого специалиста в вашем районе, опишите свою ситуацию <a href="/ask">консьержу</a>. Ставки и применимые годы меняются, поэтому считайте авторитетным государственный портал. Источник: Единая контактная точка, businessincyprus.gov.cy.</p>', 'Cyprus tax and VAT explained: bands, thresholds and deadlines', 'Φορολογία και VAT στην Κύπρο: κλίμακες, όρια και προθεσμίες', 'Impozite și VAT în Cipru pe înțelesul tuturor: tranșe, praguri și termene', 'الضرائب وVAT في قبرص بالتفصيل: الشرائح والحدود والمواعيد النهائية', 'Steuern und VAT in Zypern erklärt: Stufen, Schwellenwerte und Fristen', 'Podatki i VAT na Cyprze w pigułce: przedziały, progi i terminy', 'Налоги и НДС на Кипре: шкала, пороги и сроки', 'Cyprus income tax bands, the 15,600 euro VAT threshold, the TAX FOR ALL portal and every filing deadline, in one plain-language guide for residents and businesses.', 'Οι κλίμακες του φόρου εισοδήματος στην Κύπρο, το όριο των 15.600 ευρώ για το VAT, η πύλη TAX FOR ALL και όλες οι προθεσμίες υποβολής, σε έναν κατανοητό οδηγό για κατοίκους και επιχειρήσεις.', 'Tranșele de impozit pe venit din Cipru, pragul de VAT de 15.600 de euro, portalul TAX FOR ALL și toate termenele de depunere, într-un ghid pe înțelesul tuturor pentru rezidenți și companii.', 'شرائح ضريبة الدخل في قبرص، وحد VAT البالغ 15,600 يورو، وبوابة TAX FOR ALL، وكل موعد نهائي لتقديم الإقرارات، في دليل واحد بلغة واضحة للمقيمين والشركات.', 'Zyperns Einkommensteuerstufen, die VAT-Schwelle von 15.600 Euro, das Portal TAX FOR ALL und alle Abgabefristen, in einem verständlichen Leitfaden für Einwohner und Unternehmen.', 'Cypryjskie przedziały podatku dochodowego, próg VAT 15 600 euro, portal TAX FOR ALL i wszystkie terminy składania deklaracji w jednym przystępnym przewodniku dla mieszkańców i firm.', 'Кипрская шкала подоходного налога, порог по НДС в 15 600 евро, портал TAX FOR ALL и все сроки подачи деклараций в одном понятном руководстве для резидентов и бизнеса.', array['Tax','VAT','Doing business','Cyprus']::text[], array['Φορολογία','VAT','Επιχειρείν','Κύπρος']::text[], array['Impozite','VAT','Afaceri','Cipru']::text[], array['الضرائب','VAT','ممارسة الأعمال','قبرص']::text[], array['Steuern','VAT','Geschäftstätigkeit','Zypern']::text[], array['Podatki','VAT','Prowadzenie działalności','Cypr']::text[], array['Налоги','НДС','Ведение бизнеса','Кипр']::text[]),
('cyprus-regulated-professions-licensing', 'business', 'The Cyprus Lifestyle Desk', 'published', now() - interval '17 hours', 6, array['Licensing','Regulated professions','Doing business','Cyprus']::text[], 'Getting licensed: the regulated professions of Cyprus', 'Αδειοδότηση: τα ρυθμιζόμενα επαγγέλματα της Κύπρου', 'Obținerea licenței: profesiile reglementate din Cipru', 'الحصول على الترخيص: المهن المنظَّمة في قبرص', 'Die Zulassung erlangen: die reglementierten Berufe Zyperns', 'Zdobywanie licencji: zawody regulowane na Cyprze', 'Получение лицензии: регулируемые профессии Кипра', 'Roughly 180 activities need a permit before you can trade, from estate agent to pharmacist. Here is how the licence system works and what it takes.', 'Περίπου 180 δραστηριότητες χρειάζονται άδεια πριν μπορέσετε να δραστηριοποιηθείτε, από κτηματομεσίτη μέχρι φαρμακοποιό. Δείτε πώς λειτουργεί το σύστημα αδειοδότησης και τι απαιτείται.', 'Aproximativ 180 de activități au nevoie de o autorizație înainte de a putea funcționa, de la agent imobiliar până la farmacist. Iată cum funcționează sistemul de licențiere și ce presupune.', 'نحو 180 نشاطاً تحتاج إلى تصريح قبل أن تتمكن من مزاولة العمل، من الوكيل العقاري إلى الصيدلي. وإليك كيف يعمل نظام الترخيص وما الذي يتطلبه.', 'Rund 180 Tätigkeiten brauchen eine Genehmigung, bevor Sie tätig werden dürfen, vom Immobilienmakler bis zum Apotheker. Hier steht, wie das Zulassungssystem funktioniert und was dazu nötig ist.', 'Około 180 rodzajów działalności wymaga zezwolenia, zanim będziesz mógł rozpocząć pracę, od pośrednika nieruchomości po farmaceutę. Oto jak działa system licencji i czego wymaga.', 'Около 180 видов деятельности требуют разрешения, прежде чем вы сможете начать работу, от агента по недвижимости до фармацевта. Вот как работает система лицензирования и что для этого нужно.', 'How Cyprus licenses regulated professions and activities: the single point of contact, the competent authorities, and worked examples for estate agents, pharmacists, doctors, lawyers and accountants.', 'Πώς η Κύπρος αδειοδοτεί τα ρυθμιζόμενα επαγγέλματα και τις δραστηριότητες: το ενιαίο κέντρο εξυπηρέτησης, οι αρμόδιες αρχές και πρακτικά παραδείγματα για κτηματομεσίτες, φαρμακοποιούς, γιατρούς, δικηγόρους και λογιστές.', 'Cum licențiază Cipru profesiile și activitățile reglementate: punctul de contact unic, autoritățile competente și exemple concrete pentru agenți imobiliari, farmaciști, medici, avocați și contabili.', 'كيف ترخّص قبرص المهن والأنشطة المنظَّمة: نقطة الاتصال الموحّدة، والجهات المختصة، وأمثلة تطبيقية للوكلاء العقاريين والصيادلة والأطباء والمحامين والمحاسبين.', 'Wie Zypern reglementierte Berufe und Tätigkeiten zulässt: der einheitliche Ansprechpartner, die zuständigen Behörden und durchgerechnete Beispiele für Immobilienmakler, Apotheker, Ärzte, Anwälte und Buchhalter.', 'Jak Cypr licencjonuje zawody i rodzaje działalności regulowanej: pojedynczy punkt kontaktowy, właściwe organy oraz konkretne przykłady dla pośredników nieruchomości, farmaceutów, lekarzy, prawników i księgowych.', 'Как Кипр лицензирует регулируемые профессии и виды деятельности: единая контактная точка, компетентные органы и наглядные примеры для агентов по недвижимости, фармацевтов, врачей, юристов и бухгалтеров.', '<p>Some businesses you can simply start. Others, roughly 180 regulated activities in Cyprus, need a licence, a registration or a permit before you may trade at all. The good news is that they all follow the same logic, and one portal points you to the right door.</p><h2>One point of contact</h2><p>Regulated activities are searchable through the Point of Single Contact on the businessincyprus.gov.cy portal, under the Ministry of Energy, Commerce and Industry. The regulated sectors include Agriculture and Veterinary Services, Construction and Engineering, Education, Firearms and Explosives, Health, Welfare and Beauty, Mass Media Communication, Metrology, Professional Services, Radiocommunication Services, Tourism and Leisure, Transport and Logistics, Wholesale and Retail Trade, and Cross-Border Provision of Services. The portal directs you to the competent authority for each.</p><h2>What a licence actually involves</h2><p>Every licence follows a pattern: a competent authority, a set of qualifications, often an examination, a fee, and a decision window. A few real examples show the shape of it. An estate agent registers with the Real Estate Agents Registration Council in Strovolos, sits a written examination on property and town-planning law, pays 100 euros to apply, 350 for the certificate and 250 for the annual licence, and is answered within three months. A pharmacy is licensed by the Pharmacy Board, must be owned or majority-controlled by a registered pharmacist, carries no fee, and passes three on-site inspections before approval. A doctor registers with the Cyprus Medical Council, needs Greek at level C1 and twelve months of clinical service, and pays 300 euros to join the register.</p><h2>The professional trades</h2><p>Advocates are entered on the Register of Advocates by the Supreme Court, licensed annually by the Bar Council, and must complete a pupillage of at least twelve months. Accountants and auditors are authorised by the Institute of Certified Public Accountants of Cyprus after examinations and three years of practical experience. In each case the route is the same: confirm the authority, meet the qualification, pass the exam, pay the fee, and wait out the decision period.</p><h2>Check before you commit</h2><p>Because the exact requirements and fees are set by each authority and change over time, confirm your specific activity on the official portal before you sign a lease or enrol in a course. For the legal and professional help to get licensed cleanly, see our <a href="/directory/g/professional">professional services directory</a>, or tell <a href="/ask">the concierge</a> which profession you are entering. Source: Point of Single Contact, businessincyprus.gov.cy.</p>', '<p>Ορισμένες επιχειρήσεις μπορείτε απλώς να τις ξεκινήσετε. Άλλες, περίπου 180 ρυθμιζόμενες δραστηριότητες στην Κύπρο, χρειάζονται άδεια, εγγραφή ή έγκριση προτού μπορέσετε καν να δραστηριοποιηθείτε. Τα καλά νέα είναι ότι όλες ακολουθούν την ίδια λογική, και μία πύλη σάς κατευθύνει στη σωστή πόρτα.</p><h2>Ένα ενιαίο κέντρο εξυπηρέτησης</h2><p>Οι ρυθμιζόμενες δραστηριότητες αναζητούνται μέσω του Ενιαίου Κέντρου Εξυπηρέτησης στην πύλη businessincyprus.gov.cy, υπό το Υπουργείο Ενέργειας, Εμπορίου και Βιομηχανίας. Οι ρυθμιζόμενοι τομείς περιλαμβάνουν τη Γεωργία και τις Κτηνιατρικές Υπηρεσίες, τις Κατασκευές και τη Μηχανική, την Εκπαίδευση, τα Πυροβόλα Όπλα και τα Εκρηκτικά, την Υγεία, την Πρόνοια και την Αισθητική, την Επικοινωνία Μέσων Μαζικής Ενημέρωσης, τη Μετρολογία, τις Επαγγελματικές Υπηρεσίες, τις Υπηρεσίες Ραδιοεπικοινωνιών, τον Τουρισμό και την Αναψυχή, τις Μεταφορές και την Εφοδιαστική, το Χονδρικό και Λιανικό Εμπόριο, και τη Διασυνοριακή Παροχή Υπηρεσιών. Η πύλη σάς κατευθύνει στην αρμόδια αρχή για την καθεμία.</p><h2>Τι περιλαμβάνει στην πράξη μια άδεια</h2><p>Κάθε άδεια ακολουθεί ένα μοτίβο: μια αρμόδια αρχή, ένα σύνολο προσόντων, συχνά μια εξέταση, ένα τέλος και ένα χρονικό περιθώριο για την απόφαση. Μερικά πραγματικά παραδείγματα δείχνουν τη μορφή της. Ένας κτηματομεσίτης εγγράφεται στο Συμβούλιο Εγγραφής Κτηματομεσιτών στον Στρόβολο, δίνει γραπτή εξέταση στο δίκαιο της ακίνητης ιδιοκτησίας και της πολεοδομίας, καταβάλλει 100 ευρώ για την αίτηση, 350 για το πιστοποιητικό και 250 για την ετήσια άδεια, και λαμβάνει απάντηση εντός τριών μηνών. Ένα φαρμακείο αδειοδοτείται από το Συμβούλιο Φαρμακευτικής, πρέπει να ανήκει ή να ελέγχεται κατά πλειοψηφία από εγγεγραμμένο φαρμακοποιό, δεν συνεπάγεται τέλος, και περνά τρεις επιτόπιους ελέγχους πριν από την έγκριση. Ένας γιατρός εγγράφεται στο Ιατρικό Συμβούλιο Κύπρου, χρειάζεται ελληνική γλώσσα σε επίπεδο C1 και δώδεκα μήνες κλινικής υπηρεσίας, και καταβάλλει 300 ευρώ για να εγγραφεί στο μητρώο.</p><h2>Τα ελευθέρια επαγγέλματα</h2><p>Οι δικηγόροι εγγράφονται στο Μητρώο Δικηγόρων από το Ανώτατο Δικαστήριο, αδειοδοτούνται ετησίως από τον Παγκύπριο Δικηγορικό Σύλλογο και πρέπει να ολοκληρώσουν άσκηση διάρκειας τουλάχιστον δώδεκα μηνών. Οι λογιστές και οι ελεγκτές εξουσιοδοτούνται από τον Σύνδεσμο Εγκεκριμένων Λογιστών Κύπρου έπειτα από εξετάσεις και τρία χρόνια πρακτικής εμπειρίας. Σε κάθε περίπτωση η διαδρομή είναι η ίδια: επιβεβαιώστε την αρχή, καλύψτε το προσόν, περάστε την εξέταση, καταβάλετε το τέλος και αναμείνετε το διάστημα λήψης της απόφασης.</p><h2>Ελέγξτε πριν δεσμευτείτε</h2><p>Επειδή οι ακριβείς απαιτήσεις και τα τέλη καθορίζονται από κάθε αρχή και αλλάζουν με τον χρόνο, επιβεβαιώστε τη συγκεκριμένη δραστηριότητά σας στην επίσημη πύλη προτού υπογράψετε μίσθωση ή εγγραφείτε σε κάποιο πρόγραμμα σπουδών. Για τη νομική και επαγγελματική βοήθεια ώστε να αδειοδοτηθείτε σωστά, δείτε τον <a href="/directory/g/professional">κατάλογο επαγγελματικών υπηρεσιών</a> μας, ή πείτε στον <a href="/ask">σύμβουλο εξυπηρέτησης</a> ποιο επάγγελμα ξεκινάτε. Πηγή: Ενιαίο Κέντρο Εξυπηρέτησης, businessincyprus.gov.cy.</p>', '<p>Unele afaceri le poți porni pur și simplu. Altele, aproximativ 180 de activități reglementate în Cipru, au nevoie de o licență, o înregistrare sau o autorizație înainte de a putea funcționa. Vestea bună este că toate urmează aceeași logică, iar un singur portal te îndrumă către ușa potrivită.</p><h2>Un punct unic de contact</h2><p>Activitățile reglementate pot fi căutate prin Punctul de Contact Unic de pe portalul businessincyprus.gov.cy, în cadrul Ministerului Energiei, Comerțului și Industriei. Sectoarele reglementate includ Agricultura și Serviciile Veterinare, Construcțiile și Ingineria, Educația, Armele de Foc și Explozibilii, Sănătatea, Bunăstarea și Înfrumusețarea, Comunicarea prin Mass-Media, Metrologia, Serviciile Profesionale, Serviciile de Radiocomunicații, Turismul și Agrementul, Transportul și Logistica, Comerțul cu Ridicata și cu Amănuntul, precum și Prestarea Transfrontalieră de Servicii. Portalul te îndrumă către autoritatea competentă pentru fiecare.</p><h2>Ce presupune de fapt o licență</h2><p>Fiecare licență urmează un tipar: o autoritate competentă, un set de calificări, adesea un examen, o taxă și un termen de decizie. Câteva exemple reale îi arată forma. Un agent imobiliar se înregistrează la Consiliul de Înregistrare a Agenților Imobiliari din Strovolos, susține un examen scris privind dreptul proprietății și dreptul urbanismului, plătește 100 de euro pentru cerere, 350 pentru certificat și 250 pentru licența anuală, și primește răspuns în termen de trei luni. O farmacie este licențiată de Consiliul Farmaceutic, trebuie să fie deținută sau controlată majoritar de un farmacist înregistrat, nu implică nicio taxă și trece prin trei inspecții la fața locului înainte de aprobare. Un medic se înregistrează la Consiliul Medical din Cipru, are nevoie de limba greacă la nivel C1 și de douăsprezece luni de activitate clinică, și plătește 300 de euro pentru a se înscrie în registru.</p><h2>Profesiile liberale</h2><p>Avocații sunt înscriși în Registrul Avocaților de către Curtea Supremă, sunt licențiați anual de Consiliul Baroului și trebuie să efectueze un stagiu de cel puțin douăsprezece luni. Contabilii și auditorii sunt autorizați de Institutul Contabililor Publici Autorizați din Cipru după examene și trei ani de experiență practică. În fiecare caz, traseul este același: confirmă autoritatea, îndeplinește calificarea, treci examenul, plătește taxa și așteaptă expirarea perioadei de decizie.</p><h2>Verifică înainte de a te angaja</h2><p>Deoarece cerințele și taxele exacte sunt stabilite de fiecare autoritate și se schimbă în timp, confirmă activitatea ta specifică pe portalul oficial înainte de a semna un contract de închiriere sau de a te înscrie la un curs. Pentru ajutorul juridic și profesional necesar pentru a obține licența în mod corect, consultă <a href="/directory/g/professional">directorul nostru de servicii profesionale</a> sau spune-i <a href="/ask">concierge-ului</a> ce profesie începi. Sursă: Punctul de Contact Unic, businessincyprus.gov.cy.</p>', '<p>بعض الأنشطة التجارية يمكنك ببساطة أن تبدأها. وأخرى، نحو 180 نشاطاً منظَّماً في قبرص، تحتاج إلى ترخيص أو تسجيل أو تصريح قبل أن يُسمح لك بمزاولة العمل على الإطلاق. والخبر السار أنها جميعاً تتبع المنطق نفسه، وبوابة واحدة تدلّك على الباب الصحيح.</p><h2>نقطة اتصال واحدة</h2><p>يمكن البحث عن الأنشطة المنظَّمة من خلال نقطة الاتصال الموحّدة على بوابة businessincyprus.gov.cy، التابعة لوزارة الطاقة والتجارة والصناعة. وتشمل القطاعات المنظَّمة الزراعة والخدمات البيطرية، والبناء والهندسة، والتعليم، والأسلحة النارية والمتفجرات، والصحة والرعاية والتجميل، والاتصال عبر وسائل الإعلام الجماهيرية، والمترولوجيا، والخدمات المهنية، وخدمات الاتصالات اللاسلكية، والسياحة والترفيه، والنقل والخدمات اللوجستية، وتجارة الجملة والتجزئة، وتقديم الخدمات عبر الحدود. وتوجّهك البوابة إلى الجهة المختصة بكل منها.</p><h2>ما الذي يتضمنه الترخيص فعلاً</h2><p>يتبع كل ترخيص نمطاً واحداً: جهة مختصة، ومجموعة من المؤهلات، وغالباً امتحان، ورسم، ومهلة للبتّ. وتُظهر بضعة أمثلة واقعية شكل الأمر. فالوكيل العقاري يسجّل لدى مجلس تسجيل الوكلاء العقاريين في ستروفولوس، ويجتاز امتحاناً كتابياً في قانون العقارات والتخطيط العمراني، ويدفع 100 يورو للتقديم، و350 للشهادة، و250 للترخيص السنوي، ويتلقى الرد خلال ثلاثة أشهر. أما الصيدلية فيرخّصها مجلس الصيدلة، ويجب أن يمتلكها صيدلي مسجّل أو يسيطر عليها بالأغلبية، وهي معفاة من الرسوم، وتجتاز ثلاث عمليات تفتيش ميداني قبل الموافقة. والطبيب يسجّل لدى المجلس الطبي القبرصي، ويحتاج إلى اللغة اليونانية بمستوى C1 واثني عشر شهراً من الخدمة السريرية، ويدفع 300 يورو للانضمام إلى السجل.</p><h2>المهن الحرة</h2><p>يُقيَّد المحامون في سجل المحامين لدى المحكمة العليا، ويُرخَّص لهم سنوياً من نقابة المحامين، وعليهم إتمام تدريب مهني لا تقل مدته عن اثني عشر شهراً. أما المحاسبون ومدققو الحسابات فيُعتمدون من معهد المحاسبين القانونيين المعتمدين في قبرص بعد اجتياز الامتحانات وثلاث سنوات من الخبرة العملية. وفي كل حالة يكون المسار نفسه: تأكيد الجهة، واستيفاء المؤهل، واجتياز الامتحان، ودفع الرسم، وانتظار انقضاء مدة البتّ.</p><h2>تحقّق قبل أن تلتزم</h2><p>لأن المتطلبات والرسوم الدقيقة تحددها كل جهة وتتغير بمرور الوقت، تأكّد من نشاطك المحدد على البوابة الرسمية قبل أن توقّع عقد إيجار أو تسجّل في دورة. وللحصول على المساعدة القانونية والمهنية للترخيص بسلاسة، اطّلع على <a href="/directory/g/professional">دليل الخدمات المهنية</a> لدينا، أو أخبر <a href="/ask">الكونسيرج</a> بالمهنة التي تنوي مزاولتها. المصدر: نقطة الاتصال الموحّدة، businessincyprus.gov.cy.</p>', '<p>Manche Unternehmen können Sie einfach starten. Andere, rund 180 reglementierte Tätigkeiten in Zypern, brauchen eine Zulassung, eine Registrierung oder eine Genehmigung, bevor Sie überhaupt tätig werden dürfen. Die gute Nachricht: Sie folgen alle derselben Logik, und ein Portal weist Ihnen die richtige Tür.</p><h2>Ein Ansprechpartner</h2><p>Reglementierte Tätigkeiten lassen sich über den einheitlichen Ansprechpartner auf dem Portal businessincyprus.gov.cy recherchieren, angesiedelt beim Ministerium für Energie, Handel und Industrie. Zu den reglementierten Bereichen gehören Landwirtschaft und Veterinärdienste, Bau und Ingenieurwesen, Bildung, Feuerwaffen und Sprengstoffe, Gesundheit, Wohlfahrt und Schönheitspflege, Massenmedienkommunikation, Messwesen, professionelle Dienstleistungen, Funkkommunikationsdienste, Tourismus und Freizeit, Verkehr und Logistik, Groß- und Einzelhandel sowie die grenzüberschreitende Erbringung von Dienstleistungen. Das Portal leitet Sie jeweils an die zuständige Behörde weiter.</p><h2>Was eine Zulassung tatsächlich umfasst</h2><p>Jede Zulassung folgt einem Muster: eine zuständige Behörde, ein Katalog an Qualifikationen, oft eine Prüfung, eine Gebühr und ein Entscheidungszeitraum. Einige reale Beispiele zeigen, wie das aussieht. Ein Immobilienmakler lässt sich beim Rat für die Registrierung von Immobilienmaklern in Strovolos eintragen, legt eine schriftliche Prüfung zum Immobilien- und Stadtplanungsrecht ab, zahlt 100 Euro für den Antrag, 350 für das Zertifikat und 250 für die jährliche Zulassung und erhält innerhalb von drei Monaten Bescheid. Eine Apotheke wird vom Apothekenrat zugelassen, muss einem eingetragenen Apotheker gehören oder mehrheitlich von ihm kontrolliert werden, ist gebührenfrei und durchläuft vor der Genehmigung drei Vor-Ort-Inspektionen. Ein Arzt lässt sich beim zyprischen Ärzterat eintragen, benötigt Griechisch auf Niveau C1 und zwölf Monate klinischen Dienst und zahlt 300 Euro für die Aufnahme in das Register.</p><h2>Die freien Berufe</h2><p>Rechtsanwälte werden vom Obersten Gerichtshof in das Anwaltsregister eingetragen, jährlich von der Rechtsanwaltskammer zugelassen und müssen ein Referendariat von mindestens zwölf Monaten absolvieren. Buchhalter und Wirtschaftsprüfer werden vom Institut der zugelassenen Wirtschaftsprüfer Zyperns nach Prüfungen und drei Jahren praktischer Erfahrung zugelassen. In jedem Fall ist der Weg derselbe: die Behörde bestätigen, die Qualifikation erfüllen, die Prüfung bestehen, die Gebühr zahlen und den Entscheidungszeitraum abwarten.</p><h2>Prüfen, bevor Sie sich festlegen</h2><p>Da die genauen Anforderungen und Gebühren von jeder Behörde festgelegt werden und sich im Lauf der Zeit ändern, bestätigen Sie Ihre konkrete Tätigkeit auf dem offiziellen Portal, bevor Sie einen Mietvertrag unterschreiben oder sich für einen Kurs einschreiben. Für die rechtliche und fachliche Unterstützung, um die Zulassung sauber zu erhalten, sehen Sie sich unser <a href="/directory/g/professional">Verzeichnis professioneller Dienstleistungen</a> an, oder sagen Sie <a href="/ask">dem Concierge</a>, welchen Beruf Sie ergreifen. Quelle: Einheitlicher Ansprechpartner, businessincyprus.gov.cy.</p>', '<p>Niektóre rodzaje działalności możesz po prostu rozpocząć. Inne, czyli około 180 rodzajów działalności regulowanej na Cyprze, wymagają licencji, rejestracji lub zezwolenia, zanim w ogóle będziesz mógł działać. Dobra wiadomość jest taka, że wszystkie kierują się tą samą logiką, a jeden portal wskazuje właściwe drzwi.</p><h2>Jeden punkt kontaktowy</h2><p>Działalność regulowaną można wyszukać za pośrednictwem Pojedynczego Punktu Kontaktowego na portalu businessincyprus.gov.cy, prowadzonym przez Ministerstwo Energii, Handlu i Przemysłu. Do sektorów regulowanych należą rolnictwo i usługi weterynaryjne, budownictwo i inżynieria, edukacja, broń palna i materiały wybuchowe, zdrowie, opieka i uroda, media masowe, metrologia, usługi profesjonalne, usługi radiokomunikacyjne, turystyka i wypoczynek, transport i logistyka, handel hurtowy i detaliczny oraz transgraniczne świadczenie usług. Portal kieruje cię do organu właściwego dla każdego z nich.</p><h2>Co tak naprawdę obejmuje licencja</h2><p>Każda licencja przebiega według tego samego schematu: właściwy organ, zestaw kwalifikacji, często egzamin, opłata oraz termin wydania decyzji. Kilka rzeczywistych przykładów pokazuje, jak to wygląda. Pośrednik nieruchomości rejestruje się w Radzie Rejestracji Pośredników Nieruchomości w Strovolos, przystępuje do egzaminu pisemnego z prawa nieruchomości i planowania przestrzennego, płaci 100 euro za wniosek, 350 euro za świadectwo i 250 euro za roczną licencję, a odpowiedź otrzymuje w ciągu trzech miesięcy. Apteka uzyskuje licencję od Rady Aptekarskiej, musi być własnością lub pozostawać pod kontrolą większościową zarejestrowanego farmaceuty, nie wiąże się z żadną opłatą i przechodzi trzy kontrole na miejscu przed wydaniem zgody. Lekarz rejestruje się w Cypryjskiej Radzie Lekarskiej, musi znać język grecki na poziomie C1 oraz odbyć dwanaście miesięcy pracy klinicznej i płaci 300 euro za wpis do rejestru.</p><h2>Zawody profesjonalne</h2><p>Adwokaci są wpisywani na listę adwokatów przez Sąd Najwyższy, corocznie licencjonowani przez Radę Adwokacką i muszą odbyć aplikację trwającą co najmniej dwanaście miesięcy. Księgowi i biegli rewidenci uzyskują uprawnienia od Instytutu Dyplomowanych Księgowych Cypru po zdaniu egzaminów i trzech latach praktyki zawodowej. W każdym przypadku droga jest taka sama: potwierdź właściwy organ, spełnij wymagania kwalifikacyjne, zdaj egzamin, wnieś opłatę i odczekaj okres wydania decyzji.</p><h2>Sprawdź, zanim się zaangażujesz</h2><p>Ponieważ dokładne wymagania i opłaty ustala każdy organ z osobna i zmieniają się one w czasie, potwierdź swój konkretny rodzaj działalności na oficjalnym portalu, zanim podpiszesz umowę najmu lub zapiszesz się na kurs. Po pomoc prawną i profesjonalną, dzięki której uzyskasz licencję bez komplikacji, zajrzyj do naszego <a href="/directory/g/professional">katalogu usług profesjonalnych</a> lub powiedz <a href="/ask">konsjerżowi</a>, jaki zawód zamierzasz wykonywać. Źródło: Pojedynczy Punkt Kontaktowy, businessincyprus.gov.cy.</p>', '<p>Некоторые виды деятельности можно просто начать. Другие, а это около 180 регулируемых видов деятельности на Кипре, требуют лицензии, регистрации или разрешения, прежде чем вы вообще сможете работать. Хорошая новость в том, что все они подчиняются одной и той же логике, а единый портал укажет вам нужную дверь.</p><h2>Единая контактная точка</h2><p>Регулируемые виды деятельности можно найти через Единую контактную точку на портале businessincyprus.gov.cy, который ведет Министерство энергетики, торговли и промышленности. К регулируемым секторам относятся сельское хозяйство и ветеринарные услуги, строительство и инженерное дело, образование, огнестрельное оружие и взрывчатые вещества, здравоохранение, социальное обеспечение и индустрия красоты, средства массовой информации, метрология, профессиональные услуги, услуги радиосвязи, туризм и отдых, транспорт и логистика, оптовая и розничная торговля, а также трансграничное оказание услуг. Портал направляет вас к компетентному органу по каждому из них.</p><h2>Что на самом деле включает лицензия</h2><p>Каждая лицензия следует одной схеме: компетентный орган, набор квалификаций, часто экзамен, сбор и срок принятия решения. Несколько реальных примеров показывают, как это выглядит. Агент по недвижимости регистрируется в Совете по регистрации агентов по недвижимости в Строволосе, сдает письменный экзамен по праву недвижимости и градостроительному праву, платит 100 евро за подачу заявления, 350 евро за свидетельство и 250 евро за годовую лицензию и получает ответ в течение трех месяцев. Аптека получает лицензию от Фармацевтического совета, должна принадлежать зарегистрированному фармацевту или находиться под его контролем на уровне контрольного пакета, не облагается сбором и проходит три выездные проверки до получения одобрения. Врач регистрируется в Медицинском совете Кипра, должен владеть греческим языком на уровне C1 и иметь двенадцать месяцев клинической практики, и платит 300 евро за внесение в реестр.</p><h2>Профессиональные специальности</h2><p>Адвокаты вносятся в Реестр адвокатов Верховным судом, ежегодно лицензируются Советом адвокатов и должны пройти стажировку продолжительностью не менее двенадцати месяцев. Бухгалтеры и аудиторы получают допуск от Института дипломированных бухгалтеров Кипра после экзаменов и трех лет практического опыта. В каждом случае путь один и тот же: подтвердите компетентный орган, выполните квалификационные требования, сдайте экзамен, уплатите сбор и дождитесь окончания срока принятия решения.</p><h2>Проверьте, прежде чем взять на себя обязательства</h2><p>Поскольку точные требования и сборы устанавливает каждый орган по отдельности и со временем они меняются, подтвердите свой конкретный вид деятельности на официальном портале, прежде чем подписывать договор аренды или записываться на курс. За юридической и профессиональной помощью, чтобы получить лицензию без осложнений, обратитесь к нашему <a href="/directory/g/professional">каталогу профессиональных услуг</a> или сообщите <a href="/ask">консьержу</a>, какую профессию вы осваиваете. Источник: Единая контактная точка, businessincyprus.gov.cy.</p>', 'Regulated professions in Cyprus: licences, authorities and fees', 'Ρυθμιζόμενα επαγγέλματα στην Κύπρο: άδειες, αρχές και τέλη', 'Profesii reglementate în Cipru: licențe, autorități și taxe', 'المهن المنظَّمة في قبرص: التراخيص والجهات والرسوم', 'Reglementierte Berufe in Zypern: Zulassungen, Behörden und Gebühren', 'Zawody regulowane na Cyprze: licencje, organy i opłaty', 'Регулируемые профессии на Кипре: лицензии, органы и сборы', 'A guide to licensing regulated professions in Cyprus, the competent authorities and worked examples for estate agents, pharmacists, doctors, lawyers and accountants.', 'Ένας οδηγός για την αδειοδότηση των ρυθμιζόμενων επαγγελμάτων στην Κύπρο, τις αρμόδιες αρχές και πρακτικά παραδείγματα για κτηματομεσίτες, φαρμακοποιούς, γιατρούς, δικηγόρους και λογιστές.', 'Un ghid pentru licențierea profesiilor reglementate în Cipru, autoritățile competente și exemple concrete pentru agenți imobiliari, farmaciști, medici, avocați și contabili.', 'دليل لترخيص المهن المنظَّمة في قبرص، والجهات المختصة، وأمثلة تطبيقية للوكلاء العقاريين والصيادلة والأطباء والمحامين والمحاسبين.', 'Ein Leitfaden zur Zulassung reglementierter Berufe in Zypern, den zuständigen Behörden und durchgerechneten Beispielen für Immobilienmakler, Apotheker, Ärzte, Anwälte und Buchhalter.', 'Przewodnik po licencjonowaniu zawodów regulowanych na Cyprze, właściwe organy oraz konkretne przykłady dla pośredników nieruchomości, farmaceutów, lekarzy, prawników i księgowych.', 'Руководство по лицензированию регулируемых профессий на Кипре, компетентные органы и наглядные примеры для агентов по недвижимости, фармацевтов, врачей, юристов и бухгалтеров.', array['Licensing','Regulated professions','Doing business','Cyprus']::text[], array['Αδειοδότηση','Ρυθμιζόμενα επαγγέλματα','Επιχειρείν','Κύπρος']::text[], array['Licențiere','Profesii reglementate','Afaceri','Cipru']::text[], array['الترخيص','المهن المنظَّمة','ممارسة الأعمال','قبرص']::text[], array['Zulassung','Reglementierte Berufe','Geschäftstätigkeit','Zypern']::text[], array['Licencjonowanie','Zawody regulowane','Prowadzenie działalności','Cypr']::text[], array['Лицензирование','Регулируемые профессии','Ведение бизнеса','Кипр']::text[]),
('cyprus-social-insurance-and-hiring', 'business', 'The Cyprus Lifestyle Desk', 'published', now() - interval '23 hours', 6, array['Employment','Social insurance','Hiring','Cyprus']::text[], 'Hiring in Cyprus: social insurance and employer duties', 'Προσλήψεις στην Κύπρο: κοινωνικές ασφαλίσεις και υποχρεώσεις του εργοδότη', 'Angajarea în Cipru: asigurările sociale și obligațiile angajatorului', 'التوظيف في قبرص: التأمينات الاجتماعية وواجبات صاحب العمل', 'Einstellen in Zypern: Sozialversicherung und Arbeitgeberpflichten', 'Zatrudnianie na Cyprze: ubezpieczenie społeczne i obowiązki pracodawcy', 'Наем персонала на Кипре: социальное страхование и обязанности работодателя', 'Before your first employee starts, you register, you notify, and you learn the contribution rates. The full set of employer duties, with the current figures.', 'Προτού ξεκινήσει ο πρώτος σας εργαζόμενος, εγγράφεστε, γνωστοποιείτε και μαθαίνετε τους συντελεστές των εισφορών. Το πλήρες σύνολο των υποχρεώσεων του εργοδότη, με τα τρέχοντα ποσά.', 'Înainte ca primul tău angajat să înceapă, te înregistrezi, notifici și înveți cotele de contribuții. Setul complet al obligațiilor angajatorului, cu cifrele actuale.', 'قبل أن يبدأ أول موظف لديك، تسجّل، وتُخطر، وتتعلّم معدلات الاشتراكات. المجموعة الكاملة من واجبات صاحب العمل، مع الأرقام الحالية.', 'Bevor Ihr erster Mitarbeiter anfängt, registrieren Sie sich, melden die Einstellung und lernen die Beitragssätze. Die vollständigen Arbeitgeberpflichten, mit den aktuellen Zahlen.', 'Zanim twój pierwszy pracownik zacznie pracę, rejestrujesz się, zgłaszasz zatrudnienie i poznajesz stawki składek. Pełny zestaw obowiązków pracodawcy wraz z aktualnymi danymi liczbowymi.', 'Прежде чем ваш первый сотрудник приступит к работе, вы регистрируетесь, подаете уведомление и изучаете ставки взносов. Полный набор обязанностей работодателя с актуальными цифрами.', 'What an employer must do in Cyprus: register with Social Insurance Services, notify recruitment through ERGANI, and pay the correct contributions, plus the rules on minimum wage, probation and hiring EU and non-EU staff.', 'Τι πρέπει να κάνει ένας εργοδότης στην Κύπρο: να εγγραφεί στις Υπηρεσίες Κοινωνικών Ασφαλίσεων, να γνωστοποιεί τις προσλήψεις μέσω του ΕΡΓΑΝΗ και να καταβάλλει τις σωστές εισφορές, καθώς και οι κανόνες για τον κατώτατο μισθό, τη δοκιμαστική περίοδο και την πρόσληψη προσωπικού από την ΕΕ και εκτός ΕΕ.', 'Ce trebuie să facă un angajator în Cipru: să se înregistreze la Serviciile de Asigurări Sociale, să notifice angajarea prin ERGANI și să plătească contribuțiile corecte, plus regulile privind salariul minim, perioada de probă și angajarea personalului din UE și din afara UE.', 'ما الذي يجب على صاحب العمل فعله في قبرص: التسجيل لدى دوائر التأمينات الاجتماعية، والإخطار بالتوظيف عبر نظام ERGANI، ودفع الاشتراكات الصحيحة، إضافةً إلى القواعد المتعلقة بالحد الأدنى للأجور وفترة الاختبار وتوظيف العاملين من الاتحاد الأوروبي ومن خارجه.', 'Was ein Arbeitgeber in Zypern tun muss: sich bei den Sozialversicherungsdiensten registrieren, Einstellungen über ERGANI melden und die korrekten Beiträge zahlen, dazu die Regeln zu Mindestlohn, Probezeit und der Einstellung von EU- und Nicht-EU-Personal.', 'Co musi zrobić pracodawca na Cyprze: zarejestrować się w służbie ubezpieczeń społecznych, zgłosić zatrudnienie przez system ERGANI i opłacać właściwe składki, a do tego zasady dotyczące płacy minimalnej, okresu próbnego oraz zatrudniania pracowników z UE i spoza UE.', 'Что обязан сделать работодатель на Кипре: зарегистрироваться в службе социального страхования, уведомить о найме через систему ERGANI и уплачивать правильные взносы, а также правила о минимальной заработной плате, испытательном сроке и найме сотрудников из ЕС и из стран за пределами ЕС.', '<p>Cyprus makes it straightforward to employ people, provided you do the registrations before anyone starts. Miss the order and you create problems, follow it and payroll runs itself. Here is the full set of employer duties.</p><h2>Register, then notify</h2><p>An employer first registers in the Register of Employers of the Social Insurance Services using form YKA 01-001 at the local district office. Each recruitment must then be notified no later than one day before it starts, electronically through the ERGANI system at ergani.mlsi.gov.cy. Self-employed people register on form YKA 1-008 and usually receive a social insurance number within one to two weeks.</p><h2>The contributions</h2><p>For an employee, social insurance is 22.8% of insurable earnings, split as 8.8% employer, 8.8% employee and 5.2% state. Self-employed people pay 21.8% in total, of which 16.6% is theirs and 5.2% the state''s. On top of the employee contribution, an employer also pays 1.2% to the Redundancy Fund, 0.5% to the Human Resources Development Fund and 2% to the Social Cohesion Fund. Contributions are due by the end of the calendar month following the month they relate to, and self-employed contributions are paid every three months.</p><h2>The rules of employment</h2><p>Since 1 January 2024 the national minimum wage is 1,000 euros gross for full-time employees, and 900 euros gross for the first six months of service. Employees must receive written terms of employment, the probation period is the first six months and can be extended to two years by agreement, redundancy rights apply after 104 consecutive weeks, and protection from unfair dismissal after 26 consecutive weeks. To hire an EU citizen you file form MEU1A with a fee of 20 euros per person and 20 euros for each family member who is also an EU citizen. Non-EU key personnel in companies of foreign interests need a minimum gross salary of 2,500 euros a month and a contract of two to three years.</p><h2>Set up payroll properly</h2><p>An accountant or a payroll service will register you, run the ERGANI notifications and file the monthly contributions, which is well worth it from the first hire. You will find both in our <a href="/directory/g/professional">professional services directory</a>, and <a href="/ask">the concierge</a> can match you to one near you. Figures change, so confirm the current rates on the government portal. Source: Point of Single Contact, businessincyprus.gov.cy.</p>', '<p>Η Κύπρος κάνει απλή την απασχόληση προσωπικού, αρκεί να κάνετε τις εγγραφές προτού ξεκινήσει οποιοσδήποτε. Αν χάσετε τη σειρά, δημιουργείτε προβλήματα, αν την τηρήσετε, η μισθοδοσία τρέχει μόνη της. Δείτε το πλήρες σύνολο των υποχρεώσεων του εργοδότη.</p><h2>Εγγραφή και μετά γνωστοποίηση</h2><p>Ο εργοδότης εγγράφεται πρώτα στο Μητρώο Εργοδοτών των Υπηρεσιών Κοινωνικών Ασφαλίσεων με το έντυπο YKA 01-001 στο κατά τόπον επαρχιακό γραφείο. Στη συνέχεια, κάθε πρόσληψη πρέπει να γνωστοποιείται το αργότερο μία ημέρα πριν από την έναρξή της, ηλεκτρονικά μέσω του συστήματος ΕΡΓΑΝΗ στο ergani.mlsi.gov.cy. Οι αυτοεργοδοτούμενοι εγγράφονται με το έντυπο YKA 1-008 και συνήθως λαμβάνουν αριθμό κοινωνικών ασφαλίσεων εντός μίας έως δύο εβδομάδων.</p><h2>Οι εισφορές</h2><p>Για έναν εργαζόμενο, οι κοινωνικές ασφαλίσεις ανέρχονται σε 22,8% των ασφαλιστέων αποδοχών, που κατανέμονται σε 8,8% για τον εργοδότη, 8,8% για τον εργαζόμενο και 5,2% για το κράτος. Οι αυτοεργοδοτούμενοι καταβάλλουν συνολικά 21,8%, εκ των οποίων το 16,6% τους αναλογεί και το 5,2% το κράτος. Πέραν της εισφοράς του εργαζομένου, ο εργοδότης καταβάλλει επίσης 1,2% στο Ταμείο Πλεονάζοντος Προσωπικού, 0,5% στο Ταμείο Ανάπτυξης Ανθρώπινου Δυναμικού και 2% στο Ταμείο Κοινωνικής Συνοχής. Οι εισφορές οφείλονται μέχρι το τέλος του ημερολογιακού μήνα που έπεται του μήνα στον οποίο αναφέρονται, και οι εισφορές των αυτοεργοδοτούμενων καταβάλλονται κάθε τρεις μήνες.</p><h2>Οι κανόνες της απασχόλησης</h2><p>Από την 1η Ιανουαρίου 2024 ο εθνικός κατώτατος μισθός είναι 1.000 ευρώ μεικτά για τους εργαζομένους πλήρους απασχόλησης, και 900 ευρώ μεικτά για τους πρώτους έξι μήνες υπηρεσίας. Οι εργαζόμενοι πρέπει να λαμβάνουν γραπτούς όρους απασχόλησης, η δοκιμαστική περίοδος είναι οι πρώτοι έξι μήνες και μπορεί να παραταθεί έως τα δύο έτη κατόπιν συμφωνίας, τα δικαιώματα πλεονασμού ισχύουν μετά από 104 συνεχόμενες εβδομάδες, και η προστασία από την άδικη απόλυση μετά από 26 συνεχόμενες εβδομάδες. Για να προσλάβετε πολίτη της ΕΕ υποβάλλετε το έντυπο MEU1A με τέλος 20 ευρώ ανά άτομο και 20 ευρώ για κάθε μέλος της οικογένειας που είναι επίσης πολίτης της ΕΕ. Το βασικό προσωπικό εκτός ΕΕ σε εταιρείες ξένων συμφερόντων χρειάζεται ελάχιστο μεικτό μισθό 2.500 ευρώ τον μήνα και σύμβαση δύο έως τριών ετών.</p><h2>Οργανώστε σωστά τη μισθοδοσία</h2><p>Ένας λογιστής ή μια υπηρεσία μισθοδοσίας θα σας εγγράψει, θα διεκπεραιώνει τις γνωστοποιήσεις στο ΕΡΓΑΝΗ και θα υποβάλλει τις μηνιαίες εισφορές, κάτι που αξίζει από την πρώτη κιόλας πρόσληψη. Θα βρείτε και τους δύο στον <a href="/directory/g/professional">κατάλογο επαγγελματικών υπηρεσιών</a> μας, και ο <a href="/ask">σύμβουλος εξυπηρέτησης</a> μπορεί να σας αντιστοιχίσει με κάποιον κοντά σας. Τα ποσά αλλάζουν, γι'' αυτό επιβεβαιώστε τους τρέχοντες συντελεστές στην κυβερνητική πύλη. Πηγή: Ενιαίο Κέντρο Εξυπηρέτησης, businessincyprus.gov.cy.</p>', '<p>Cipru face angajarea de personal simplă, cu condiția să faci înregistrările înainte ca cineva să înceapă. Ratează ordinea și creezi probleme, respect-o și salarizarea merge de la sine. Iată setul complet al obligațiilor angajatorului.</p><h2>Înregistrează-te, apoi notifică</h2><p>Un angajator se înregistrează mai întâi în Registrul Angajatorilor al Serviciilor de Asigurări Sociale folosind formularul YKA 01-001 la biroul districtual local. Fiecare angajare trebuie apoi notificată cu cel puțin o zi înainte de a începe, electronic prin sistemul ERGANI la ergani.mlsi.gov.cy. Lucrătorii independenți se înregistrează pe formularul YKA 1-008 și primesc de obicei un număr de asigurări sociale în una-două săptămâni.</p><h2>Contribuțiile</h2><p>Pentru un angajat, asigurările sociale reprezintă 22,8% din veniturile asigurabile, împărțite în 8,8% angajator, 8,8% angajat și 5,2% stat. Lucrătorii independenți plătesc în total 21,8%, din care 16,6% le revine lor și 5,2% statului. Pe lângă contribuția angajatului, angajatorul plătește de asemenea 1,2% la Fondul pentru Concedieri, 0,5% la Fondul de Dezvoltare a Resurselor Umane și 2% la Fondul de Coeziune Socială. Contribuțiile sunt scadente până la sfârșitul lunii calendaristice următoare celei la care se referă, iar contribuțiile lucrătorilor independenți se plătesc la fiecare trei luni.</p><h2>Regulile de angajare</h2><p>De la 1 ianuarie 2024, salariul minim național este de 1.000 de euro brut pentru angajații cu normă întreagă și de 900 de euro brut pentru primele șase luni de activitate. Angajații trebuie să primească termeni de angajare în scris, perioada de probă este reprezentată de primele șase luni și poate fi prelungită până la doi ani prin acord, drepturile de disponibilizare se aplică după 104 săptămâni consecutive, iar protecția împotriva concedierii abuzive după 26 de săptămâni consecutive. Pentru a angaja un cetățean al UE depui formularul MEU1A, cu o taxă de 20 de euro de persoană și 20 de euro pentru fiecare membru de familie care este de asemenea cetățean al UE. Personalul-cheie din afara UE din companiile cu interese străine are nevoie de un salariu brut minim de 2.500 de euro pe lună și de un contract de doi-trei ani.</p><h2>Organizează corect salarizarea</h2><p>Un contabil sau un serviciu de salarizare te va înregistra, va gestiona notificările ERGANI și va depune contribuțiile lunare, ceea ce merită pe deplin încă de la prima angajare. Îi vei găsi pe amândoi în <a href="/directory/g/professional">directorul nostru de servicii profesionale</a>, iar <a href="/ask">concierge-ul</a> te poate pune în legătură cu unul din apropierea ta. Cifrele se schimbă, așa că verifică ratele actuale pe portalul guvernamental. Sursă: Punctul de Contact Unic, businessincyprus.gov.cy.</p>', '<p>تجعل قبرص توظيف الأشخاص أمراً مباشراً، شريطة أن تنجز التسجيلات قبل أن يبدأ أي شخص. إن أخطأت الترتيب تسبّبت في مشكلات، وإن اتّبعته سارت كشوف الرواتب من تلقاء نفسها. وإليك المجموعة الكاملة من واجبات صاحب العمل.</p><h2>سجّل، ثم أخطِر</h2><p>يسجّل صاحب العمل أولاً في سجل أصحاب العمل لدى دوائر التأمينات الاجتماعية باستخدام النموذج YKA 01-001 في مكتب المقاطعة المحلي. ثم يجب الإخطار بكل عملية توظيف في موعد أقصاه يوم واحد قبل بدئها، إلكترونياً عبر نظام ERGANI على ergani.mlsi.gov.cy. ويسجّل العاملون لحسابهم الخاص باستخدام النموذج YKA 1-008 ويحصلون عادةً على رقم تأمين اجتماعي خلال أسبوع إلى أسبوعين.</p><h2>الاشتراكات</h2><p>بالنسبة للموظف، تبلغ التأمينات الاجتماعية 22.8% من الدخل القابل للتأمين، موزَّعة بواقع 8.8% على صاحب العمل، و8.8% على الموظف، و5.2% على الدولة. ويدفع العاملون لحسابهم الخاص 21.8% إجمالاً، منها 16.6% حصتهم و5.2% حصة الدولة. وإضافةً إلى اشتراك الموظف، يدفع صاحب العمل أيضاً 1.2% لصندوق الفائض العمالي، و0.5% لصندوق تنمية الموارد البشرية، و2% لصندوق التماسك الاجتماعي. وتُستحق الاشتراكات بحلول نهاية الشهر الميلادي التالي للشهر الذي تتعلق به، وتُدفع اشتراكات العاملين لحسابهم الخاص كل ثلاثة أشهر.</p><h2>قواعد التوظيف</h2><p>منذ 1 يناير 2024 يبلغ الحد الأدنى الوطني للأجور 1,000 يورو إجمالاً للموظفين بدوام كامل، و900 يورو إجمالاً خلال الأشهر الستة الأولى من الخدمة. ويجب أن يحصل الموظفون على شروط توظيف مكتوبة، وفترة الاختبار هي الأشهر الستة الأولى ويمكن تمديدها إلى سنتين بالاتفاق، وتنطبق حقوق التعويض عن الاستغناء بعد 104 أسابيع متتالية، والحماية من الفصل التعسفي بعد 26 أسبوعاً متتالياً. ولتوظيف مواطن من الاتحاد الأوروبي تقدّم النموذج MEU1A برسم قدره 20 يورو للشخص و20 يورو لكل فرد من أفراد الأسرة يكون أيضاً مواطناً في الاتحاد الأوروبي. ويحتاج الموظفون الرئيسيون من خارج الاتحاد الأوروبي في الشركات ذات المصالح الأجنبية إلى حد أدنى من الراتب الإجمالي قدره 2,500 يورو شهرياً وعقد مدته سنتان إلى ثلاث سنوات.</p><h2>أنشئ نظام الرواتب على الوجه الصحيح</h2><p>سيتولى محاسب أو خدمة كشوف رواتب تسجيلك، وإجراء إخطارات ERGANI، وتقديم الاشتراكات الشهرية، وهو أمر يستحق العناء منذ أول تعيين. وستجد كليهما في <a href="/directory/g/professional">دليل الخدمات المهنية</a> لدينا، ويستطيع <a href="/ask">الكونسيرج</a> مطابقتك مع أحدهم بالقرب منك. تتغير الأرقام، لذا تأكّد من المعدلات الحالية على البوابة الحكومية. المصدر: نقطة الاتصال الموحّدة، businessincyprus.gov.cy.</p>', '<p>Zypern macht es unkompliziert, Menschen zu beschäftigen, sofern Sie die Registrierungen erledigen, bevor jemand anfängt. Verpassen Sie die Reihenfolge, schaffen Sie Probleme; halten Sie sie ein, läuft die Lohnabrechnung von selbst. Hier stehen die vollständigen Arbeitgeberpflichten.</p><h2>Erst registrieren, dann melden</h2><p>Ein Arbeitgeber lässt sich zunächst mit dem Formular YKA 01-001 im örtlichen Bezirksbüro in das Arbeitgeberregister der Sozialversicherungsdienste eintragen. Jede Einstellung muss dann spätestens einen Tag vor ihrem Beginn elektronisch über das ERGANI-System unter ergani.mlsi.gov.cy gemeldet werden. Selbstständige registrieren sich mit dem Formular YKA 1-008 und erhalten in der Regel innerhalb von ein bis zwei Wochen eine Sozialversicherungsnummer.</p><h2>Die Beiträge</h2><p>Für einen Arbeitnehmer beträgt die Sozialversicherung 22,8 % des versicherbaren Verdienstes, aufgeteilt in 8,8 % Arbeitgeber, 8,8 % Arbeitnehmer und 5,2 % Staat. Selbstständige zahlen insgesamt 21,8 %, davon 16,6 % ihr eigener Anteil und 5,2 % der des Staates. Zusätzlich zum Arbeitnehmerbeitrag zahlt ein Arbeitgeber außerdem 1,2 % an den Abfindungsfonds, 0,5 % an den Fonds für die Entwicklung der Humanressourcen und 2 % an den Fonds für sozialen Zusammenhalt. Die Beiträge sind bis zum Ende des Kalendermonats fällig, der auf den Monat folgt, auf den sie sich beziehen, und die Beiträge Selbstständiger werden alle drei Monate gezahlt.</p><h2>Die Beschäftigungsregeln</h2><p>Seit dem 1. Januar 2024 beträgt der nationale Mindestlohn 1.000 Euro brutto für Vollzeitbeschäftigte und 900 Euro brutto für die ersten sechs Monate der Beschäftigung. Arbeitnehmer müssen schriftliche Arbeitsbedingungen erhalten, die Probezeit umfasst die ersten sechs Monate und kann einvernehmlich auf zwei Jahre verlängert werden, Abfindungsansprüche gelten nach 104 aufeinanderfolgenden Wochen und der Schutz vor ungerechtfertigter Kündigung nach 26 aufeinanderfolgenden Wochen. Um einen EU-Bürger einzustellen, reichen Sie das Formular MEU1A mit einer Gebühr von 20 Euro pro Person und 20 Euro für jedes Familienmitglied ein, das ebenfalls EU-Bürger ist. Schlüsselpersonal aus Nicht-EU-Ländern in Unternehmen mit ausländischen Interessen benötigt ein Mindestbruttogehalt von 2.500 Euro monatlich und einen Vertrag über zwei bis drei Jahre.</p><h2>Die Lohnabrechnung richtig aufsetzen</h2><p>Ein Buchhalter oder ein Lohnabrechnungsdienst registriert Sie, übernimmt die ERGANI-Meldungen und reicht die monatlichen Beiträge ein, was sich schon ab der ersten Einstellung lohnt. Beide finden Sie in unserem <a href="/directory/g/professional">Verzeichnis professioneller Dienstleistungen</a>, und <a href="/ask">der Concierge</a> kann Sie mit einem in Ihrer Nähe zusammenbringen. Die Zahlen ändern sich, bestätigen Sie daher die aktuellen Sätze auf dem Regierungsportal. Quelle: Einheitlicher Ansprechpartner, businessincyprus.gov.cy.</p>', '<p>Cypr sprawia, że zatrudnianie ludzi jest proste, pod warunkiem że dopełnisz rejestracji, zanim ktokolwiek rozpocznie pracę. Pomyl kolejność, a stworzysz sobie problemy, zachowaj ją, a lista płac prowadzi się sama. Oto pełny zestaw obowiązków pracodawcy.</p><h2>Najpierw rejestracja, potem zgłoszenie</h2><p>Pracodawca najpierw rejestruje się w rejestrze pracodawców służby ubezpieczeń społecznych na formularzu YKA 01-001 w lokalnym urzędzie okręgowym. Następnie każde zatrudnienie należy zgłosić nie później niż jeden dzień przed jego rozpoczęciem, drogą elektroniczną przez system ERGANI pod adresem ergani.mlsi.gov.cy. Osoby prowadzące działalność na własny rachunek rejestrują się na formularzu YKA 1-008 i zwykle otrzymują numer ubezpieczenia społecznego w ciągu jednego do dwóch tygodni.</p><h2>Składki</h2><p>W przypadku pracownika składka na ubezpieczenie społeczne wynosi 22,8% zarobków podlegających ubezpieczeniu i dzieli się na 8,8% po stronie pracodawcy, 8,8% po stronie pracownika oraz 5,2% po stronie państwa. Osoby prowadzące działalność na własny rachunek płacą łącznie 21,8%, z czego 16,6% przypada na nie, a 5,2% na państwo. Poza składką pracowniczą pracodawca odprowadza również 1,2% na Fundusz Odpraw, 0,5% na Fundusz Rozwoju Zasobów Ludzkich oraz 2% na Fundusz Spójności Społecznej. Składki są płatne do końca miesiąca kalendarzowego następującego po miesiącu, którego dotyczą, a składki osób samozatrudnionych opłaca się co trzy miesiące.</p><h2>Zasady zatrudnienia</h2><p>Od 1 stycznia 2024 roku krajowa płaca minimalna wynosi 1 000 euro brutto dla pracowników pełnoetatowych oraz 900 euro brutto przez pierwsze sześć miesięcy zatrudnienia. Pracownicy muszą otrzymać pisemne warunki zatrudnienia, okres próbny obejmuje pierwsze sześć miesięcy i za porozumieniem stron może zostać przedłużony do dwóch lat, prawo do odprawy przysługuje po 104 kolejnych tygodniach, a ochrona przed niesłusznym zwolnieniem po 26 kolejnych tygodniach. Aby zatrudnić obywatela UE, składasz formularz MEU1A z opłatą 20 euro za osobę oraz 20 euro za każdego członka rodziny, który również jest obywatelem UE. Kluczowy personel spoza UE w spółkach z kapitałem zagranicznym musi mieć minimalne wynagrodzenie brutto 2 500 euro miesięcznie oraz umowę na dwa do trzech lat.</p><h2>Prawidłowo ustaw listę płac</h2><p>Księgowy lub biuro obsługi płac zarejestruje cię, obsłuży zgłoszenia w systemie ERGANI i złoży miesięczne składki, co opłaca się już przy pierwszym pracowniku. Obu znajdziesz w naszym <a href="/directory/g/professional">katalogu usług profesjonalnych</a>, a <a href="/ask">konsjerż</a> może dobrać takiego specjalistę w twojej okolicy. Dane liczbowe się zmieniają, dlatego potwierdź aktualne stawki na portalu rządowym. Źródło: Pojedynczy Punkt Kontaktowy, businessincyprus.gov.cy.</p>', '<p>Кипр делает наем людей простым делом при условии, что вы завершите регистрацию до того, как кто-либо приступит к работе. Нарушьте порядок, и вы создадите себе проблемы, соблюдайте его, и расчет заработной платы идет сам собой. Вот полный набор обязанностей работодателя.</p><h2>Сначала регистрация, затем уведомление</h2><p>Работодатель сначала регистрируется в Реестре работодателей службы социального страхования по форме YKA 01-001 в местном окружном отделении. Затем о каждом найме необходимо уведомить не позднее чем за один день до его начала, в электронном виде через систему ERGANI по адресу ergani.mlsi.gov.cy. Самозанятые регистрируются по форме YKA 1-008 и обычно получают номер социального страхования в течение одной-двух недель.</p><h2>Взносы</h2><p>Для наемного работника взнос на социальное страхование составляет 22,8% страхуемого заработка и распределяется как 8,8% на работодателя, 8,8% на работника и 5,2% на государство. Самозанятые платят в общей сложности 21,8%, из которых 16,6% приходится на них, а 5,2% на государство. Помимо взноса за работника, работодатель также уплачивает 1,2% в Фонд выходных пособий, 0,5% в Фонд развития человеческих ресурсов и 2% в Фонд социальной сплоченности. Взносы подлежат уплате до конца календарного месяца, следующего за месяцем, к которому они относятся, а взносы самозанятых уплачиваются каждые три месяца.</p><h2>Правила трудоустройства</h2><p>С 1 января 2024 года национальная минимальная заработная плата составляет 1 000 евро брутто для сотрудников на полной ставке и 900 евро брутто в течение первых шести месяцев работы. Сотрудники должны получить письменные условия трудоустройства, испытательный срок составляет первые шесть месяцев и по соглашению может быть продлен до двух лет, право на выходное пособие возникает после 104 недель подряд, а защита от несправедливого увольнения после 26 недель подряд. Чтобы нанять гражданина ЕС, вы подаете форму MEU1A со сбором 20 евро за человека и 20 евро за каждого члена семьи, который также является гражданином ЕС. Ключевому персоналу из стран за пределами ЕС в компаниях с иностранным участием требуется минимальная заработная плата брутто 2 500 евро в месяц и договор на два-три года.</p><h2>Правильно организуйте расчет заработной платы</h2><p>Бухгалтер или служба расчета заработной платы зарегистрирует вас, обработает уведомления в системе ERGANI и подаст ежемесячные взносы, что вполне оправдано уже с первого нанятого сотрудника. Обоих вы найдете в нашем <a href="/directory/g/professional">каталоге профессиональных услуг</a>, а <a href="/ask">консьерж</a> может подобрать такого специалиста рядом с вами. Цифры меняются, поэтому уточните актуальные ставки на государственном портале. Источник: Единая контактная точка, businessincyprus.gov.cy.</p>', 'Hiring in Cyprus: employer duties, social insurance and contributions', 'Προσλήψεις στην Κύπρο: υποχρεώσεις εργοδότη, κοινωνικές ασφαλίσεις και εισφορές', 'Angajarea în Cipru: obligațiile angajatorului, asigurări sociale și contribuții', 'التوظيف في قبرص: واجبات صاحب العمل والتأمينات الاجتماعية والاشتراكات', 'Einstellen in Zypern: Arbeitgeberpflichten, Sozialversicherung und Beiträge', 'Zatrudnianie na Cyprze: obowiązki pracodawcy, ubezpieczenie społeczne i składki', 'Наем персонала на Кипре: обязанности работодателя, социальное страхование и взносы', 'Registering as an employer in Cyprus, ERGANI notifications, social insurance contribution rates, the minimum wage and the rules for hiring EU and non-EU staff.', 'Εγγραφή ως εργοδότης στην Κύπρο, γνωστοποιήσεις μέσω του ΕΡΓΑΝΗ, συντελεστές εισφορών κοινωνικών ασφαλίσεων, ο κατώτατος μισθός και οι κανόνες για την πρόσληψη προσωπικού από την ΕΕ και εκτός ΕΕ.', 'Înregistrarea ca angajator în Cipru, notificările ERGANI, cotele de contribuții la asigurările sociale, salariul minim și regulile pentru angajarea personalului din UE și din afara UE.', 'التسجيل بصفتك صاحب عمل في قبرص، وإخطارات ERGANI، ومعدلات اشتراكات التأمينات الاجتماعية، والحد الأدنى للأجور، وقواعد توظيف العاملين من الاتحاد الأوروبي ومن خارجه.', 'Registrierung als Arbeitgeber in Zypern, ERGANI-Meldungen, Sozialversicherungsbeitragssätze, der Mindestlohn und die Regeln für die Einstellung von EU- und Nicht-EU-Personal.', 'Rejestracja jako pracodawca na Cyprze, zgłoszenia w systemie ERGANI, stawki składek na ubezpieczenie społeczne, płaca minimalna oraz zasady zatrudniania pracowników z UE i spoza UE.', 'Регистрация в качестве работодателя на Кипре, уведомления в системе ERGANI, ставки взносов на социальное страхование, минимальная заработная плата и правила найма сотрудников из ЕС и из стран за пределами ЕС.', array['Employment','Social insurance','Hiring','Cyprus']::text[], array['Απασχόληση','Κοινωνικές ασφαλίσεις','Προσλήψεις','Κύπρος']::text[], array['Ocuparea forței de muncă','Asigurări sociale','Angajare','Cipru']::text[], array['العمل','التأمينات الاجتماعية','التوظيف','قبرص']::text[], array['Beschäftigung','Sozialversicherung','Personaleinstellung','Zypern']::text[], array['Zatrudnienie','Ubezpieczenie społeczne','Rekrutacja','Cypr']::text[], array['Трудоустройство','Социальное страхование','Наем персонала','Кипр']::text[]),
('cyprus-business-funding-and-grants', 'business', 'The Cyprus Lifestyle Desk', 'published', now() - interval '29 hours', 5, array['Funding','Grants','Doing business','Cyprus']::text[], 'Funding and grants for a Cyprus business', 'Χρηματοδότηση και επιχορηγήσεις για μια κυπριακή επιχείρηση', 'Finanțare și granturi pentru o afacere cipriotă', 'التمويل والمنح لنشاط تجاري في قبرص', 'Finanzierung und Zuschüsse für ein Unternehmen in Zypern', 'Finansowanie i dotacje dla cypryjskiej firmy', 'Финансирование и гранты для кипрского бизнеса', 'Grants that cover up to 85% of research spend, bank finance, and the tax incentives that quietly matter. Where Cyprus money actually comes from.', 'Επιχορηγήσεις που καλύπτουν έως και το 85% των δαπανών έρευνας, τραπεζική χρηματοδότηση και τα φορολογικά κίνητρα που μετρούν αθόρυβα. Από πού προέρχονται πραγματικά τα χρήματα στην Κύπρο.', 'Granturi care acoperă până la 85% din cheltuielile de cercetare, finanțare bancară și stimulentele fiscale care contează în tăcere. De unde provin cu adevărat banii în Cipru.', 'منح تغطي ما يصل إلى 85% من الإنفاق على البحث، والتمويل المصرفي، والحوافز الضريبية التي تهم في صمت. من أين يأتي المال في قبرص فعلاً.', 'Zuschüsse, die bis zu 85 % der Forschungsausgaben abdecken, Bankfinanzierung und die stillen, aber wichtigen Steueranreize. Woher das Geld in Zypern tatsächlich kommt.', 'Dotacje pokrywające do 85% wydatków na badania, finansowanie bankowe oraz zachęty podatkowe, które po cichu mają znaczenie. Skąd naprawdę pochodzą cypryjskie pieniądze.', 'Гранты, покрывающие до 85% расходов на исследования, банковское финансирование и налоговые льготы, которые незаметно играют роль. Откуда на самом деле берутся кипрские деньги.', 'The main routes to funding a business in the Republic of Cyprus: the Research and Innovation Foundation, sector bodies and banks, plus the tax incentives that support new and foreign-owned ventures.', 'Οι κύριες οδοί για τη χρηματοδότηση μιας επιχείρησης στην Κυπριακή Δημοκρατία: το Ίδρυμα Έρευνας και Καινοτομίας, οι κλαδικοί φορείς και οι τράπεζες, καθώς και τα φορολογικά κίνητρα που στηρίζουν νέα και ξένης ιδιοκτησίας εγχειρήματα.', 'Principalele căi de finanțare a unei afaceri în Republica Cipru: Fundația pentru Cercetare și Inovare, organismele sectoriale și băncile, plus stimulentele fiscale care sprijină afacerile noi și pe cele cu capital străin.', 'الطرق الرئيسية لتمويل نشاط تجاري في جمهورية قبرص: مؤسسة البحث والابتكار، والهيئات القطاعية، والبنوك، إضافةً إلى الحوافز الضريبية التي تدعم المشاريع الجديدة والمملوكة لأجانب.', 'Die wichtigsten Wege zur Finanzierung eines Unternehmens in der Republik Zypern: die Stiftung für Forschung und Innovation, Branchenstellen und Banken sowie die Steueranreize, die neue und ausländisch geführte Vorhaben unterstützen.', 'Główne drogi finansowania działalności w Republice Cypryjskiej: Fundacja na rzecz Badań i Innowacji, organy branżowe i banki, a także zachęty podatkowe wspierające nowe przedsięwzięcia i firmy z kapitałem zagranicznym.', 'Основные пути финансирования бизнеса в Республике Кипр: Фонд исследований и инноваций, отраслевые органы и банки, а также налоговые льготы, поддерживающие новые предприятия и предприятия с иностранным капиталом.', '<p>Cyprus has more support for new businesses than its size suggests, but the money rewards preparation. A clear plan, some of your own capital and the right door open most of it. Here is where funding actually comes from.</p><h2>Prepare first</h2><p>Before you approach anyone, prepare a fully detailed business plan that shows strategic potential and projected income, be ready to part-finance the initiative yourself, and expect to offer collateral, in liquid or illiquid assets, for any bank loan. Funders read the plan before they read the ask.</p><h2>The main door: research and innovation</h2><p>The Research and Innovation Foundation is the principal body financing business research, and its grants cover up to 85% of the invested capital, awarded on eligibility and qualitative criteria, with programmes listed at research.org.cy. If your venture has a research or innovation edge, this is the first place to look.</p><h2>Sector support and banks</h2><p>Beyond research, support comes from the Industry and Technology Service of the Ministry of Energy, Commerce and Industry, and, for the primary sector, from the Ministry of Agriculture and the Cyprus Agricultural Payments Organisation. Cypriot banks provide conventional debt finance for businesses that can show a plan and collateral.</p><h2>The incentives that quietly matter</h2><p>Some of the real value is in the tax code. Corporate income tax is 12.5%, and foreign nationals can qualify for a 50% exemption on annual employment income of 55,000 euros and above, subject to conditions. The Deputy Ministry of Research, Innovation and Digital Policy approves Certified Innovative Businesses, which unlocks further advantages. To build the plan and find the grants, an accountant or a business consultant is the right first call: see our <a href="/directory/g/professional">professional services directory</a> or ask <a href="/ask">the concierge</a>. Schemes and criteria change, so confirm current programmes on the government portal. Source: Point of Single Contact, businessincyprus.gov.cy.</p>', '<p>Η Κύπρος διαθέτει περισσότερη στήριξη για νέες επιχειρήσεις από όση υποδηλώνει το μέγεθός της, αλλά τα χρήματα ανταμείβουν την προετοιμασία. Ένα σαφές σχέδιο, λίγο δικό σας κεφάλαιο και η σωστή πόρτα ανοίγουν το μεγαλύτερο μέρος της. Δείτε από πού προέρχεται πραγματικά η χρηματοδότηση.</p><h2>Προετοιμαστείτε πρώτα</h2><p>Προτού απευθυνθείτε σε οποιονδήποτε, ετοιμάστε ένα πλήρως λεπτομερές επιχειρηματικό σχέδιο που να δείχνει στρατηγικές δυνατότητες και προβλεπόμενα έσοδα, να είστε έτοιμοι να συγχρηματοδοτήσετε το εγχείρημα οι ίδιοι, και να αναμένετε ότι θα προσφέρετε εξασφάλιση, σε ρευστά ή μη ρευστά περιουσιακά στοιχεία, για κάθε τραπεζικό δάνειο. Οι χρηματοδότες διαβάζουν το σχέδιο προτού διαβάσουν το αίτημα.</p><h2>Η κύρια πόρτα: έρευνα και καινοτομία</h2><p>Το Ίδρυμα Έρευνας και Καινοτομίας είναι ο κύριος φορέας που χρηματοδοτεί την επιχειρηματική έρευνα, και οι επιχορηγήσεις του καλύπτουν έως και το 85% του επενδυμένου κεφαλαίου, χορηγούμενες βάσει κριτηρίων επιλεξιμότητας και ποιοτικών κριτηρίων, με τα προγράμματα να παρατίθενται στο research.org.cy. Αν το εγχείρημά σας έχει ερευνητικό ή καινοτόμο χαρακτήρα, εδώ πρέπει να κοιτάξετε πρώτα.</p><h2>Κλαδική στήριξη και τράπεζες</h2><p>Πέρα από την έρευνα, στήριξη προσφέρεται από την Υπηρεσία Βιομηχανίας και Τεχνολογίας του Υπουργείου Ενέργειας, Εμπορίου και Βιομηχανίας, και, για τον πρωτογενή τομέα, από το Υπουργείο Γεωργίας και τον Κυπριακό Οργανισμό Αγροτικών Πληρωμών. Οι κυπριακές τράπεζες παρέχουν συμβατική δανειακή χρηματοδότηση σε επιχειρήσεις που μπορούν να παρουσιάσουν σχέδιο και εξασφάλιση.</p><h2>Τα κίνητρα που μετρούν αθόρυβα</h2><p>Μέρος της πραγματικής αξίας βρίσκεται στη φορολογική νομοθεσία. Ο εταιρικός φόρος εισοδήματος είναι 12,5%, και οι αλλοδαποί μπορούν να δικαιούνται απαλλαγή 50% επί του ετήσιου εισοδήματος από απασχόληση ύψους 55.000 ευρώ και άνω, υπό προϋποθέσεις. Το Υφυπουργείο Έρευνας, Καινοτομίας και Ψηφιακής Πολιτικής εγκρίνει τις Πιστοποιημένες Καινοτόμες Επιχειρήσεις, κάτι που ξεκλειδώνει περαιτέρω πλεονεκτήματα. Για να καταρτίσετε το σχέδιο και να βρείτε τις επιχορηγήσεις, ένας λογιστής ή ένας επιχειρηματικός σύμβουλος είναι η σωστή πρώτη επιλογή: δείτε τον <a href="/directory/g/professional">κατάλογο επαγγελματικών υπηρεσιών</a> μας ή ρωτήστε τον <a href="/ask">σύμβουλο εξυπηρέτησης</a>. Τα σχήματα και τα κριτήρια αλλάζουν, γι'' αυτό επιβεβαιώστε τα τρέχοντα προγράμματα στην κυβερνητική πύλη. Πηγή: Ενιαίο Κέντρο Εξυπηρέτησης, businessincyprus.gov.cy.</p>', '<p>Cipru are mai mult sprijin pentru afacerile noi decât sugerează dimensiunea sa, însă banii răsplătesc pregătirea. Un plan clar, o parte din capitalul propriu și ușa potrivită deschid cea mai mare parte a acestuia. Iată de unde provine în realitate finanțarea.</p><h2>Pregătește-te mai întâi</h2><p>Înainte de a te adresa cuiva, pregătește un plan de afaceri pe deplin detaliat, care să arate potențialul strategic și veniturile estimate, fii pregătit să cofinanțezi tu însuți inițiativa și așteaptă-te să oferi garanții, sub formă de active lichide sau nelichide, pentru orice împrumut bancar. Finanțatorii citesc planul înainte de a citi cererea.</p><h2>Ușa principală: cercetare și inovare</h2><p>Fundația pentru Cercetare și Inovare este principalul organism care finanțează cercetarea în afaceri, iar granturile sale acoperă până la 85% din capitalul investit, acordate pe baza criteriilor de eligibilitate și a celor calitative, cu programele enumerate la research.org.cy. Dacă afacerea ta are un avantaj în materie de cercetare sau inovare, aici trebuie să te uiți mai întâi.</p><h2>Sprijin sectorial și bănci</h2><p>Dincolo de cercetare, sprijinul vine de la Serviciul pentru Industrie și Tehnologie al Ministerului Energiei, Comerțului și Industriei și, pentru sectorul primar, de la Ministerul Agriculturii și de la Organizația Cipriotă pentru Plăți Agricole. Băncile cipriote oferă finanțare prin credit obișnuită pentru afacerile care pot prezenta un plan și garanții.</p><h2>Stimulentele care contează în tăcere</h2><p>O parte din valoarea reală se află în codul fiscal. Impozitul pe profitul companiilor este de 12,5%, iar cetățenii străini pot beneficia de o scutire de 50% pentru venitul anual din muncă de 55.000 de euro și peste, în anumite condiții. Ministerul Adjunct pentru Cercetare, Inovare și Politică Digitală aprobă Întreprinderile Inovatoare Certificate, ceea ce deblochează avantaje suplimentare. Pentru a construi planul și a găsi granturile, un contabil sau un consultant de afaceri este primul apel potrivit: consultă <a href="/directory/g/professional">directorul nostru de servicii profesionale</a> sau întreabă <a href="/ask">concierge-ul</a>. Schemele și criteriile se schimbă, așa că verifică programele actuale pe portalul guvernamental. Sursă: Punctul de Contact Unic, businessincyprus.gov.cy.</p>', '<p>لدى قبرص دعم للأنشطة التجارية الجديدة أكبر مما يوحي به حجمها، لكن المال يكافئ الاستعداد. فخطة واضحة، وبعض رأس مالك الخاص، والباب الصحيح تفتح معظمه. وإليك من أين يأتي التمويل فعلاً.</p><h2>استعدّ أولاً</h2><p>قبل أن تتوجه إلى أي جهة، أعِدّ خطة عمل مفصّلة بالكامل تُظهر الإمكانات الاستراتيجية والدخل المتوقع، وكن مستعداً لتمويل جزء من المبادرة بنفسك، وتوقّع أن تقدّم ضمانات، في صورة أصول سائلة أو غير سائلة، مقابل أي قرض مصرفي. فالممولون يقرؤون الخطة قبل أن يقرؤوا الطلب.</p><h2>الباب الرئيسي: البحث والابتكار</h2><p>مؤسسة البحث والابتكار هي الجهة الرئيسية التي تموّل البحوث التجارية، وتغطي منحها ما يصل إلى 85% من رأس المال المستثمَر، وتُمنح بناءً على معايير الأهلية والمعايير النوعية، مع إدراج البرامج على research.org.cy. وإذا كان لمشروعك ميزة بحثية أو ابتكارية، فهذا هو المكان الأول الذي تبحث فيه.</p><h2>الدعم القطاعي والبنوك</h2><p>وإلى جانب البحث، يأتي الدعم من دائرة الصناعة والتكنولوجيا في وزارة الطاقة والتجارة والصناعة، وبالنسبة للقطاع الأولي، من وزارة الزراعة والهيئة القبرصية للمدفوعات الزراعية. وتقدّم البنوك القبرصية تمويلاً بالدَّين التقليدي للأنشطة التجارية القادرة على إظهار خطة وضمانات.</p><h2>الحوافز التي تهم في صمت</h2><p>يكمن جزء من القيمة الحقيقية في قانون الضرائب. فضريبة دخل الشركات 12.5%، ويمكن للمواطنين الأجانب التأهل لإعفاء بنسبة 50% على دخل العمل السنوي البالغ 55,000 يورو فأكثر، رهناً بشروط. وتعتمد الوزارة الفرعية للبحث والابتكار والسياسة الرقمية الشركات المبتكرة المعتمَدة، وهو ما يتيح مزايا إضافية. ولبناء الخطة والعثور على المنح، يكون المحاسب أو مستشار الأعمال هو الخيار الأول الصحيح: اطّلع على <a href="/directory/g/professional">دليل الخدمات المهنية</a> لدينا أو اسأل <a href="/ask">الكونسيرج</a>. تتغير البرامج والمعايير، لذا تأكّد من البرامج الحالية على البوابة الحكومية. المصدر: نقطة الاتصال الموحّدة، businessincyprus.gov.cy.</p>', '<p>Zypern bietet neuen Unternehmen mehr Unterstützung, als seine Größe vermuten lässt, doch das Geld belohnt Vorbereitung. Ein klarer Plan, etwas eigenes Kapital und die richtige Tür öffnen das meiste davon. Hier steht, woher die Finanzierung tatsächlich kommt.</p><h2>Zuerst vorbereiten</h2><p>Bevor Sie an jemanden herantreten, erstellen Sie einen vollständig ausgearbeiteten Geschäftsplan, der strategisches Potenzial und die prognostizierten Einnahmen aufzeigt, seien Sie bereit, die Initiative teilweise selbst zu finanzieren, und rechnen Sie damit, für jeden Bankkredit Sicherheiten in Form liquider oder illiquider Vermögenswerte zu stellen. Geldgeber lesen den Plan, bevor sie die Bitte lesen.</p><h2>Die Haupttür: Forschung und Innovation</h2><p>Die Stiftung für Forschung und Innovation ist die wichtigste Stelle zur Finanzierung von Unternehmensforschung, und ihre Zuschüsse decken bis zu 85 % des investierten Kapitals ab, vergeben nach Zulassungs- und Qualitätskriterien, mit den Programmen aufgelistet unter research.org.cy. Wenn Ihr Vorhaben einen Forschungs- oder Innovationsvorsprung hat, ist dies die erste Anlaufstelle.</p><h2>Branchenförderung und Banken</h2><p>Über die Forschung hinaus kommt Unterstützung vom Dienst für Industrie und Technologie des Ministeriums für Energie, Handel und Industrie und, für den Primärsektor, vom Landwirtschaftsministerium und der zyprischen Organisation für Agrarzahlungen. Zyprische Banken bieten konventionelle Fremdfinanzierung für Unternehmen, die einen Plan und Sicherheiten vorweisen können.</p><h2>Die Anreize, die im Stillen zählen</h2><p>Ein Teil des wahren Werts steckt im Steuerrecht. Die Körperschaftsteuer beträgt 12,5 %, und ausländische Staatsangehörige können unter bestimmten Voraussetzungen eine Befreiung von 50 % auf ein jährliches Arbeitseinkommen von 55.000 Euro und mehr in Anspruch nehmen. Das stellvertretende Ministerium für Forschung, Innovation und Digitalpolitik erkennt zertifizierte innovative Unternehmen an, was weitere Vorteile eröffnet. Um den Plan zu erstellen und die Zuschüsse zu finden, ist ein Buchhalter oder ein Unternehmensberater die richtige erste Anlaufstelle: Sehen Sie sich unser <a href="/directory/g/professional">Verzeichnis professioneller Dienstleistungen</a> an oder fragen Sie <a href="/ask">den Concierge</a>. Programme und Kriterien ändern sich, bestätigen Sie daher aktuelle Programme auf dem Regierungsportal. Quelle: Einheitlicher Ansprechpartner, businessincyprus.gov.cy.</p>', '<p>Cypr oferuje nowym firmom więcej wsparcia, niż sugerowałaby jego wielkość, ale pieniądze nagradzają przygotowanie. Jasny plan, część własnego kapitału i właściwe drzwi otwierają większość z nich. Oto skąd naprawdę pochodzi finansowanie.</p><h2>Najpierw przygotowanie</h2><p>Zanim zwrócisz się do kogokolwiek, przygotuj w pełni szczegółowy biznesplan, który pokaże potencjał strategiczny i prognozowane przychody, bądź gotów częściowo sfinansować przedsięwzięcie z własnych środków i licz się z koniecznością ustanowienia zabezpieczenia, w postaci aktywów płynnych lub niepłynnych, przy każdym kredycie bankowym. Podmioty finansujące czytają plan, zanim przeczytają samą prośbę.</p><h2>Główne drzwi: badania i innowacje</h2><p>Fundacja na rzecz Badań i Innowacji jest głównym podmiotem finansującym badania biznesowe, a jej dotacje pokrywają do 85% zainwestowanego kapitału, przyznawane na podstawie kryteriów kwalifikowalności i jakościowych, przy czym programy są wymienione na stronie research.org.cy. Jeśli twoje przedsięwzięcie ma przewagę badawczą lub innowacyjną, to jest pierwsze miejsce, do którego warto zajrzeć.</p><h2>Wsparcie branżowe i banki</h2><p>Poza badaniami wsparcie zapewnia Służba ds. Przemysłu i Technologii przy Ministerstwie Energii, Handlu i Przemysłu, a w sektorze pierwotnym Ministerstwo Rolnictwa oraz Cypryjska Organizacja Płatności Rolnych. Cypryjskie banki udzielają klasycznego finansowania dłużnego firmom, które mogą przedstawić plan i zabezpieczenie.</p><h2>Zachęty, które po cichu mają znaczenie</h2><p>Część rzeczywistej wartości kryje się w przepisach podatkowych. Podatek dochodowy od osób prawnych wynosi 12,5%, a cudzoziemcy mogą kwalifikować się do 50% zwolnienia od rocznego dochodu z zatrudnienia w wysokości 55 000 euro i więcej, z zastrzeżeniem określonych warunków. Zastępcze Ministerstwo ds. Badań, Innowacji i Polityki Cyfrowej zatwierdza certyfikowane przedsiębiorstwa innowacyjne, co otwiera dostęp do dalszych korzyści. Aby zbudować plan i znaleźć dotacje, właściwym pierwszym krokiem jest księgowy lub doradca biznesowy: zajrzyj do naszego <a href="/directory/g/professional">katalogu usług profesjonalnych</a> lub zapytaj <a href="/ask">konsjerża</a>. Programy i kryteria się zmieniają, dlatego potwierdź aktualne programy na portalu rządowym. Źródło: Pojedynczy Punkt Kontaktowy, businessincyprus.gov.cy.</p>', '<p>На Кипре больше поддержки для новых предприятий, чем можно предположить по его размеру, но деньги вознаграждают подготовку. Четкий план, часть собственного капитала и правильная дверь открывают большинство из них. Вот откуда на самом деле поступает финансирование.</p><h2>Сначала подготовка</h2><p>Прежде чем к кому-либо обращаться, подготовьте полностью детализированный бизнес-план, который демонстрирует стратегический потенциал и прогнозируемый доход, будьте готовы частично профинансировать начинание самостоятельно и рассчитывайте на необходимость предоставить обеспечение, в виде ликвидных или неликвидных активов, по любому банковскому кредиту. Те, кто предоставляет финансирование, читают план прежде, чем читают саму просьбу.</p><h2>Главная дверь: исследования и инновации</h2><p>Фонд исследований и инноваций является главным органом, финансирующим бизнес-исследования, и его гранты покрывают до 85% вложенного капитала, присуждаемые по критериям соответствия и качественным критериям, а программы перечислены на сайте research.org.cy. Если у вашего предприятия есть исследовательское или инновационное преимущество, это первое место, куда стоит обратиться.</p><h2>Отраслевая поддержка и банки</h2><p>Помимо исследований, поддержку оказывает Служба промышленности и технологий Министерства энергетики, торговли и промышленности, а в первичном секторе Министерство сельского хозяйства и Кипрская организация сельскохозяйственных платежей. Кипрские банки предоставляют обычное долговое финансирование предприятиям, которые могут представить план и обеспечение.</p><h2>Льготы, которые незаметно играют роль</h2><p>Часть реальной ценности заложена в налоговом законодательстве. Налог на прибыль составляет 12,5%, а иностранные граждане могут претендовать на 50% освобождение от годового дохода от трудовой деятельности в размере 55 000 евро и выше, при соблюдении условий. Заместительное министерство исследований, инноваций и цифровой политики утверждает сертифицированные инновационные предприятия, что открывает доступ к дальнейшим преимуществам. Чтобы составить план и найти гранты, правильным первым шагом будет бухгалтер или бизнес-консультант: обратитесь к нашему <a href="/directory/g/professional">каталогу профессиональных услуг</a> или спросите <a href="/ask">консьержа</a>. Программы и критерии меняются, поэтому уточните действующие программы на государственном портале. Источник: Единая контактная точка, businessincyprus.gov.cy.</p>', 'Funding and grants for businesses in Cyprus', 'Χρηματοδότηση και επιχορηγήσεις για επιχειρήσεις στην Κύπρο', 'Finanțare și granturi pentru afaceri în Cipru', 'التمويل والمنح للأنشطة التجارية في قبرص', 'Finanzierung und Zuschüsse für Unternehmen in Zypern', 'Finansowanie i dotacje dla firm na Cyprze', 'Финансирование и гранты для бизнеса на Кипре', 'How to fund a business in Cyprus: Research and Innovation Foundation grants up to 85%, sector support, bank finance and the tax incentives for new and foreign ventures.', 'Πώς να χρηματοδοτήσετε μια επιχείρηση στην Κύπρο: επιχορηγήσεις του Ιδρύματος Έρευνας και Καινοτομίας έως 85%, κλαδική στήριξη, τραπεζική χρηματοδότηση και τα φορολογικά κίνητρα για νέα και ξένα εγχειρήματα.', 'Cum să finanțezi o afacere în Cipru: granturi de până la 85% de la Fundația pentru Cercetare și Inovare, sprijin sectorial, finanțare bancară și stimulentele fiscale pentru afacerile noi și străine.', 'كيف تموّل نشاطاً تجارياً في قبرص: منح مؤسسة البحث والابتكار التي تصل إلى 85%، والدعم القطاعي، والتمويل المصرفي، والحوافز الضريبية للمشاريع الجديدة والأجنبية.', 'Wie Sie ein Unternehmen in Zypern finanzieren: Zuschüsse der Stiftung für Forschung und Innovation von bis zu 85 %, Branchenförderung, Bankfinanzierung und die Steueranreize für neue und ausländische Vorhaben.', 'Jak sfinansować firmę na Cyprze: dotacje Fundacji na rzecz Badań i Innowacji do 85%, wsparcie branżowe, finansowanie bankowe oraz zachęty podatkowe dla nowych i zagranicznych przedsięwzięć.', 'Как профинансировать бизнес на Кипре: гранты Фонда исследований и инноваций до 85%, отраслевая поддержка, банковское финансирование и налоговые льготы для новых и иностранных предприятий.', array['Funding','Grants','Doing business','Cyprus']::text[], array['Χρηματοδότηση','Επιχορηγήσεις','Επιχειρείν','Κύπρος']::text[], array['Finanțare','Granturi','Afaceri','Cipru']::text[], array['التمويل','المنح','ممارسة الأعمال','قبرص']::text[], array['Finanzierung','Zuschüsse','Geschäftstätigkeit','Zypern']::text[], array['Finansowanie','Dotacje','Prowadzenie działalności','Cypr']::text[], array['Финансирование','Гранты','Ведение бизнеса','Кипр']::text[])
on conflict (slug) do nothing;

-- report
select slug, category, status,
       (title_de is not null) as de, (title_pl is not null) as pl, (title_ru is not null) as ru
from public.blog_posts
where slug in ('setting-up-a-company-in-cyprus','cyprus-tax-and-vat-guide','cyprus-regulated-professions-licensing','cyprus-social-insurance-and-hiring','cyprus-business-funding-and-grants')
order by slug;
